INSERT INTO Pokémon (pokedex_number, region_id, name, image, species, pri_type, sec_type, description)
VALUES 
(1, NULL, 'Bulbasaur', '1.png', 'Seed Pokémon', 'Grass', 'Poison', 'For some time after its birth, it grows by taking nourishment from the seed on its back.'),
(2, NULL, 'Ivysaur', '2.png', 'Seed Pokémon', 'Grass', 'Poison', 'When the bud on its back starts swelling, a sweet aroma wafts to indicate the flower''s coming bloom.'),
(3, NULL, 'Venusaur', '3.png', 'Seed Pokémon', 'Grass', 'Poison', 'After a rainy day, the flower on its back smells stronger. The scent attracts other Pokémon.'),
(4, NULL, 'Charmander', '4.png', 'Lizard Pokémon', 'Fire', NULL, 'The fire on the tip of its tail is a measure of its life. If the Pokémon is healthy, its tail burns intensely.'),
(5, NULL, 'Charmeleon', '5.png', 'Flame Pokémon', 'Fire', NULL, 'In the rocky mountains where Charmeleon live, their fiery tails shine at night like stars.'),
(6, NULL, 'Charizard', '6.png', 'Flame Pokémon', 'Fire', 'Flying', 'It is said that Charizard''s fire burns hotter if it has experienced harsh battles.'),
(7, NULL, 'Squirtle', '7.png', 'Tiny Turtle Pokémon', 'Water', NULL, 'It hides in its shell to protect itself, then strikes back with spouts of water at every opportunity.'),
(8, NULL, 'Wartortle', '8.png', 'Turtle Pokémon', 'Water', NULL, 'It is said to live 10,000 years. Its furry tail is popular as a symbol of longevity.'),
(9, NULL, 'Blastoise', '9.png', 'Shellfish Pokémon', 'Water', NULL, 'The jets of water it spouts from the rocket cannons on its shell can punch through thick steel.'),
(10, NULL, 'Caterpie', '10.png', 'Worm Pokémon', 'Bug', NULL, 'It releases a stench from its red antennae to repel enemies. It grows by molting repeatedly.'),
(11, NULL, 'Metapod', '11.png', 'Cocoon Pokémon', 'Bug', NULL, 'A steel-hard shell protects its tender body. The Pokémon quietly endures hardships while awaiting evolution.'),
(12, NULL, 'Butterfree', '12.png', 'Butterfly Pokémon', 'Bug', 'Flying', 'It loves the nectar of flowers and can locate flower patches that have even tiny amounts of pollen.'),
(13, NULL, 'Weedle', '13.png', 'Hairy Bug Pokémon', 'Bug', 'Poison', 'It eats its weight in leaves every day. It fends off attackers with the needle on its head.'),
(14, NULL, 'Kakuna', '14.png', 'Cocoon Pokémon', 'Bug', 'Poison', 'While awaiting evolution, it hides from predators under leaves and in nooks of branches.'),
(15, NULL, 'Beedrill', '15.png', 'Poison Bee Pokémon', 'Bug', 'Poison', 'Its best attack involves flying around at high speed, striking with poison needles, then flying off.'),
(16, NULL, 'Pidgey', '16.png', 'Tiny Bird Pokémon', 'Normal', 'Flying', 'It is docile and prefers to avoid conflict. If disturbed, however, it can ferociously strike back.'),
(17, NULL, 'Pidgeotto', '17.png', 'Bird Pokémon', 'Normal', 'Flying', 'It flies over its wide territory in search of prey, downing it with its highly developed claws.'),
(18, NULL, 'Pidgeot', '18.png', 'Bird Pokémon', 'Normal', 'Flying', 'By flapping its wings with all its might, Pidgeot can make a gust of wind capable of bending tall trees.'),
(19, NULL, 'Rattata', '19.png', 'Mouse Pokémon', 'Normal', NULL, 'It''s cautious in the extreme, and its hardy vitality lets it live in any kind of environment.'),
(19, 1, 'Rattata', '19-alolalola.png', 'Mouse Pokémon', 'Dark', 'Normal', 'Its whiskers provide it with a keen sense of smell, enabling it to pick up the scent of hidden food and locate it instantly.'),
(20, NULL, 'Raticate', '20.png', 'Mouse Pokémon', 'Normal', NULL, 'It whittles down its constantly growing fangs by gnawing on hard things. It can chew apart cinder block walls.'),
(20, 1, 'Raticate', '20-alola.png', 'Mouse Pokémon', 'Dark', 'Normal', 'It makes its Rattata underlings gather food for it, dining solely on the most nutritious and delicious fare.'),
(21, NULL, 'Spearow', '21.png', 'Tiny Bird Pokémon', 'Normal', 'Flying', 'It flaps its small wings busily to fly. Using its beak, it searches in grass for prey.'),
(22, NULL, 'Fearow', '22.png', 'Beak Pokémon', 'Normal', 'Flying', 'It has the stamina to fly all day on its broad wings. It fights by using its sharp beak.'),
(23, NULL, 'Ekans', '23.png', 'Snake Pokémon', 'Poison', NULL, 'It sneaks through grass without making a sound and strikes unsuspecting prey from behind.'),
(24, NULL, 'Arbok', '24.png', 'Cobra Pokémon', 'Poison', NULL, 'The pattern on its belly is for intimidation. It constricts foes while they are frozen in fear.'),
(25, NULL, 'Pikachu', '25.png', 'Mouse Pokémon', 'Electric', NULL, 'When it is angered, it immediately discharges the energy stored in the pouches in its cheeks.'),
(26, NULL, 'Raichu', '26.png', 'Mouse Pokémon', 'Electric', NULL, 'Its tail discharges electricity into the ground, protecting it from getting shocked.'),
(26, 1, 'Raichu', '26-alola.png', 'Mouse Pokémon', 'Electric', 'Psychic', 'This Pokémon rides on its tail while it uses its psychic powers to levitate. It attacks with star-shaped thunderbolts.'),
(27, NULL, 'Sandshrew', '27.png', 'Mouse Pokémon', 'Ground', NULL, 'To protect itself from attackers, it curls up into a ball. It lives in arid regions with minimal rainfall.'),
(27, 1, 'Sandshrew', '27-alola.png', 'Mouse Pokémon', 'Ice', 'Steel', 'It lives in snowy mountains on southern islands. When a blizzard rolls in, this Pokémon hunkers down in the snow to avoid getting blown away.'),
(28, NULL, 'Sandslash', '28.png', 'Mouse Pokémon', 'Ground', NULL, 'It curls up, then rolls into foes with its back. Its sharp spines inflict severe damage.'),
(28, 1, 'Sandslash', '28-alola.png', 'Mouse Pokémon', 'Ice', 'Steel', 'Many people climb snowy mountains, hoping to see the icy spikes of these Pokémon glistening in the light of dawn.'),
(29, NULL, 'Nidoran (female)', '29.png', 'Poison Pin Pokémon', 'Poison', NULL, 'While this Pokémon does not prefer to fight, even one drop of the venom it secretes from its barbs can be fatal.'),
(30, NULL, 'Nidorina', '30.png', 'Poison Pin Pokémon', 'Poison', NULL, 'When it senses danger, it raises all the barbs on its body. These barbs grow more slowly than Nidorino''s.'),
(31, NULL, 'Nidoqueen', '31.png', 'Drill Pokémon', 'Poison', 'Ground', 'Its entire body is armored with hard scales. It will protect the young in its burrow with its life.'),
(32, NULL, 'Nidoran (male)', '32.png', 'Poison Pin Pokémon', 'Poison', NULL, 'It scans its surroundings by raising its ears out of the grass. Its toxic horn is for protection.'),
(33, NULL, 'Nidorino', '33.png', 'Poison Pin Pokémon', 'Poison', NULL, 'It has a violent disposition and stabs foes with its horn, which oozes venom upon impact.'),
(34, NULL, 'Nidoking', '34.png', 'Drill Pokémon', 'Poison', 'Ground', 'One swing of its mighty tail can snap a telephone pole as if it were a matchstick.'),
(35, NULL, 'Clefairy', '35.png', 'Fairy Pokémon', 'Fairy', NULL, 'It can be found in quiet mountain areas on a full moon''s night. Its dancing and its tiny, faintly glowing wings confer upon it a lovely fairylike quality.'),
(36, NULL, 'Clefable', '36.png', 'Fairy Pokémon', 'Fairy', NULL, 'Legend says that on clear, quiet nights, it listens for the voices of its kin living on the moon. I, too, often think of my homeland, so far away.'),
(37, NULL, 'Vulpix', '37.png', 'Fox Pokémon', 'Fire', NULL, 'In its belly burns a fire, which Vulpix spits out in the form of fireballs. When young, this Pokémon has but one white tail. As the Pokémon matures, this single tail splits into six.'),
(37, 1, 'Vulpix', '37-alola.png', 'Fox Pokémon', 'Ice', NULL, 'These Pokémon live in packs in the snowy mountains and defend themselves with icy breath. I suspect this species changed its form to adapt to the frigid climate.'),
(38, NULL, 'Ninetales', '38.png', 'Fox Pokémon', 'Fire', NULL, 'The coat of gleaming golden fur is quite magnificent. This species is said to store sacred power in its nine long tails and to live for a millennium.'),
(38, 1, 'Ninetales', '38-alola.png', 'Fox Pokémon', 'Ice', NULL, 'Dwells on sacred peaks perpetually covered in snow. Said to appear to virtuous people who have lost their way on mountain paths—it then guides them back down to the mountain''s base.'),
(39, NULL, 'Jigglypuff', '39.png', 'Balloon Pokémon', 'Normal', 'Fairy', 'When its huge eyes waver, it sings a mysteriously soothing melody that lulls its enemies to sleep.'),
(40, NULL, 'Wigglytuff', '40.png', 'Balloon Pokémon', 'Normal', 'Fairy', 'The rich, fluffy fur that covers its body feels so good that anyone who feels it can''t stop touching it.'),
(41, NULL, 'Zubat', '41.png', 'Bat Pokémon', 'Poison', 'Flying', 'Makes its home in gloomy caves. Atrophied eyes have left this Pokémon blind, so it scans its surroundings via sound waves that it emits from its mouth as it flies.'),
(42, NULL, 'Golbat', '42.png', 'Bat Pokémon', 'Poison', 'Flying', 'It sinks its sharp fangs into other creatures and slurps up their blood. A closer look at the fangs reveals that they are hollow and akin to straws.'),
(43, NULL, 'Oddish', '43.png', 'Weed Pokémon', 'Grass', 'Poison', 'It often plants its root feet in the ground during the day and sows seeds as it walks about at night.'),
(44, NULL, 'Gloom', '44.png', 'Weed Pokémon', 'Grass', 'Poison', 'The nectar it drools from its mouth smells so atrocious that it can make noses curl from more than a mile away.'),
(45, NULL, 'Vileplume', '45.png', 'Flower Pokémon', 'Grass', 'Poison', 'Its petals are the largest in the world. As it walks, it scatters extremely allergenic pollen.'),
(46, NULL, 'Paras', '46.png', 'Mushroom Pokémon', 'Bug', 'Grass', 'Sometimes seen at the foot of trees in humid forests. The mushrooms on its back—called tochukaso—are not present on infant specimens and instead emerge as Paras matures.'),
(47, NULL, 'Parasect', '47.png', 'Mushroom Pokémon', 'Bug', 'Grass', 'Mushroom-lacking specimens of this Pokémon lie unmoving in the forest, lending credence to the hypothesis that the large mushroom is in control of Parasect''s actions.'),
(48, NULL, 'Venonat', '48.png', 'Insect Pokémon', 'Bug', 'Poison', 'Its eyes act as radar, enabling it to be active in darkness. The eyes can also shoot powerful beams.'),
(49, NULL, 'Venomoth', '49.png', 'Poison Moth Pokémon', 'Bug', 'Poison', 'The wings are covered with dustlike scales. Every time it flaps its wings, it looses highly toxic dust.'),
(50, NULL, 'Diglett', '50.png', 'Mole Pokémon', 'Ground', NULL, 'It lives about one yard underground, where it feeds on plant roots. It sometimes appears aboveground.'),
(50, NULL, 'Diglett', '50-alola.png', 'Mole Pokémon', 'Ground', 'Steel', 'Its three hairs change shape depending on Diglett''s mood. They''re a useful communication tool among these Pokémon.'),
(51, NULL, 'Dugtrio', '51.png', 'Mole Pokémon', 'Ground', NULL, 'Its three heads bob separately up and down to loosen the soil nearby, making it easier for it to burrow.'),
(51, NULL, 'Dugtrio', '51-alola.png', 'Mole Pokémon', 'Ground', 'Steel', 'Their beautiful, metallic whiskers create a sort of protective helmet on their heads, and they also function as highly precise sensors.'),
(52, NULL, 'Meowth', '52.png', 'Scratch Cat Pokémon', 'Normal', NULL, 'It loves things that sparkle. When it sees a shiny object, the gold coin on its head shines, too.'),
(52, 1, 'Meowth', '52-alola.png', 'Scratch Cat Pokémon', 'Dark', NULL, 'Deeply proud and keenly smart, this Pokémon moves with cunning during battle and relentlessly attacks enemies'' weak points.'),
(52, 2, 'Meowth', '52-galar.png', 'Scratch Cat Pokémon', 'Steel', NULL, 'These daring Pokémon have coins on their foreheads. Darker coins are harder, and harder coins garner more respect among Meowth.'),
(53, NULL, 'Persian', '53.png', 'Classy Cat Pokémon', 'Normal', NULL, 'It has a vicious temperament. Beware if it raises its tail straight up. This is a signal that it is about to pounce and bite.'),
(53, 1, 'Persian', '53-alola.png', 'Classy Cat Pokémon', 'Dark', NULL, 'This Pokémon is one tough opponent. Not only does it have formidable physical abilities, but it''s also not above fighting dirty.'),
(54, NULL, 'Psyduck', '54.png', 'Duck Pokémon', 'Water', NULL, 'It is constantly wracked by a headache. When the headache turns intense, it begins using mysterious powers.'),
(55, NULL, 'Golduck', '55.png', 'Duck Pokémon', 'Water', NULL, 'When it swims at full speed using its long, webbed limbs, its forehead somehow begins to glow.'),
(56, NULL, 'Mankey', '56.png', 'Pig Monkey Pokémon', 'Fighting', NULL, 'It is extremely quick to anger. It could be docile one moment, then thrashing away the next instant.'),
(57, NULL, 'Primeape', '57.png', 'Pig Monkey Pokémon', 'Fighting', NULL, 'It becomes wildly furious if it even senses someone looking at it. It chases anyone that meets its glare.'),
(58, NULL, 'Growlithe', '58.png', 'Puppy Pokémon', 'Fire', NULL, 'It has a brave and trustworthy nature. It fearlessly stands up to bigger and stronger foes.'),
(58, 3, 'Growlithe', '58-hisui.png', 'Scout Pokémon', 'Fire', 'Rock', 'They patrol their territory in pairs. I believe the igneous rock components in the fur of this species are the result of volcanic activity in its habitat.'),
(59, NULL, 'Arcanine', '59.png', ' Pokémon', 'Fire', NULL, 'Its magnificent bark conveys a sense of majesty. Anyone hearing it can''t help but grovel before it.'),
(59, 3, 'Arcanine', '59-hisui.png', ' Pokémon', 'Fire', 'Rock', 'Snaps at its foes with fangs cloaked in blazing flame. Despite its bulk, it deftly feints every which way, leading opponents on a deceptively merry chase as it all but dances around them.'),
(60, NULL, 'Poliwag', '60.png', 'Tadpole Pokémon', 'Water', NULL, 'Its skin is so thin, its internal organs are visible. It has trouble walking on its newly grown feet.'),
(61, NULL, 'Poliwhirl', '61.png', 'Tadpole Pokémon', 'Water', NULL, 'The spiral pattern on its belly subtly undulates. Staring at it gradually causes drowsiness.'),
(62, NULL, 'Poliwrath', '62.png', 'Tadpole Pokémon', 'Water', 'Fighting', 'With its extremely tough muscles, it could keep swimming in the Pacific Ocean without resting.'),
(63, NULL, 'Abra', '63.png', 'Psi Pokémon', 'Psychic', NULL, 'Spends 18 hours of the day sleeping. Even while asleep, Abra can control its psychic powers—should danger approach, the Pokémon will simply teleport away.'),
(64, NULL, 'Kadabra', '64.png', 'Psi Pokémon', 'Psychic', NULL, 'There are rumors that a child with mystical powers became a Kadabra; however, this remains unverified. I suspect that the spoon Kadabra holds enhances its brain waves.'),
(65, NULL, 'Alakazam', '65.png', 'Psi Pokémon', 'Psychic', NULL, 'The longer Alakazam lives, the larger and heavier its head becomes. Our tests have shown that the strength of its psychic powers correlates positively to the weight of its head.'),
(66, NULL, 'Machop', '66.png', 'Superpower Pokémon', 'Fighting', NULL, 'Though as small as a child, it has strength enough to easily throw a well-built adult. Striving to become ever stronger, Machop trains by carrying a Graveler on its shoulders.'),
(67, NULL, 'Machoke', '67.png', 'Superpower Pokémon', 'Fighting', NULL, 'A sturdy creature boasting a robust physique and boundless stamina. Loves training above all else and voluntarily assists with tasks such as construction and clearing land.'),
(68, NULL, 'Machamp', '68.png', 'Superpower Pokémon', 'Fighting', NULL, 'In close combat, its four arms afford it offensive and defensive supremacy. In but a blink, this valiant Pokémon can overwhelm its foes with more than 1,000 blows from its fists.'),
(69, NULL, 'Bellsprout', '69.png', 'Flower Pokémon', 'Grass', 'Poison', 'It prefers hot and humid environments. It is quick at capturing prey with its vines.'),
(70, NULL, 'Weepinbell', '70.png', 'Flycatcher Pokémon', 'Grass', 'Poison', 'This Pokémon has the appearance of a plant. It captures unwary prey by dousing them with a toxic powder.'),
(71, NULL, 'Victreebel', '71.png', 'Flycatcher Pokémon', 'Grass', 'Poison', 'In its mouth, it pools a fragrant nectar-like fluid. The fluid is really an acid that dissolves anything.'),
(72, NULL, 'Tentacool', '72.png', 'Jellyfish Pokémon', 'Water', 'Poison', 'They fire beams from the glassy, magenta orbs that resemble eyes atop their heads, and they drift in shallow seas. During low tide, they can sometimes be found on beaches, desiccated.'),
(73, NULL, 'Tentacruel', '73.png', 'Jellyfish Pokémon', 'Water', 'Poison', 'It has 80 tentacles, each with a venomous tip. These tentacles are also extendible, lengthening when Tentacruel attempts to catch prey. Use caution.'),
(74, NULL, 'Geodude', '74.png', 'Rock Pokémon', 'Rock', 'Ground', 'Makes its home in mountainous regions, using its arms to climb along harsh mountain roads. Can be troublesome—carelessly kicking one will cause it to fly into a rage and chase after you.'),
(74, 1, 'Geodude', '74-alola.png', 'Rock Pokémon', 'Rock', 'Electric', 'Its stone head is imbued with electricity and magnetism. If you carelessly step on one, you''ll be in for a painful shock.'),
(75, NULL, 'Graveler', '75.png', 'Rock Pokémon', 'Rock', 'Ground', 'Dwells in holes dug into sheer walls of stone. It enjoys rolling down slopes as though it were a boulder during a rockfall, so keep an eye upward while traversing mountain roads.'),
(75, 1, 'Graveler', '75-alola.png', 'Rock Pokémon', 'Rock', 'Electric', 'When it comes rolling down a mountain path, anything in its way gets zapped by electricity and sent flying.'),
(76, NULL, 'Golem', '76.png', 'Rock Pokémon', 'Rock', 'Ground', 'The rocklike shell is shed each year. The cast-off shell then crumbles, reverting to a mass of soil, which can be spread across fields to promote crop growth.'),
(76, 1, 'Golem', '76-alola.png', 'Rock Pokémon', 'Rock', 'Electric', 'It uses magnetism to accelerate and fire off rocks tinged with electricity. Even if it doesn''t score a direct hit, the jolt of electricity will do the job.'),
(77, NULL, 'Ponyta', '77.png', 'Fire Horse Pokémon', 'Fire', NULL, 'These Pokémon live in herds out in the grassland. Newborn foals lack their fiery manes, which will develop about an hour after birth.'),
(77, 2, 'Ponyta', '77-galar.png', 'Unique Horn Pokémon', 'Psychic', NULL, 'This Pokémon will look into your eyes and read the contents of your heart. If it finds evil there, it promptly hides away.'),
(78, NULL, 'Rapidash', '78.png', 'Fire Horse Pokémon', 'Fire', NULL, 'Fiery mane aglow, Rapidash darts like an arrow across the land. This prodigiously swift creature can traverse the vast region of Hisui in a day and a half.'),
(78, 2, 'Rapidash', '78-galar.png', 'Unique Horn Pokémon', 'Psychic', 'Fairy', 'Brave and prideful, this Pokémon dashes airily through the forest, its steps aided by the psychic power stored in the fur on its fetlocks.'),
(79, NULL, 'Slowpoke', '79.png', 'Dopey Pokémon', 'Water', 'Psychic', 'It is always vacantly lost in thought, but no one knows what it is thinking about. It is good at fishing with its tail.'),
(79, 2, 'Slowpoke', '79-galar.png', 'Dopey Pokémon', 'Psychic', NULL, 'Because Galarian Slowpoke eat the seeds of a plant that grows only in Galar, their tails have developed a spicy flavor.'),
(80, NULL, 'Slowbro', '80.png', 'Hermit Crab Pokémon', 'Water', 'Psychic', 'If the tail-biting Shellder is thrown off in a harsh battle, this Pokémon reverts to being an ordinary Slowpoke.'),
(80, 2, 'Slowbro', '80-galar.png', 'Hermit Crab Pokémon', 'Poison', 'Psychic', 'If this Pokémon squeezes the tongue of the Shellder biting it, the Shellder will launch a toxic liquid from the tip of its shell.'),
(81, NULL, 'Magnemite', '81.png', 'Magnet Pokémon', 'Electric', 'Steel', 'It moves while constantly hovering. It discharges electromagnetic waves and so on from the units at its sides.'),
(28, NULL, 'Magneton', '82.png', 'Magnet Pokémon', 'Electric', 'Steel', 'Three Magnemite are linked by a strong magnetic force. Earaches will occur if you get too close.'),
(83, NULL, 'Farfetch''d', '83.png', 'Wild Duck Pokémon', 'Normal', 'Flying', 'It can''t live without the stalk it holds. That''s why it defends the stalk from attackers with its life.'),
(83, 2, 'Farfetch''d', '83-galar.png', 'Wild Duck Pokémon', 'Fighting', NULL, 'The Farfetch''d of the Galar region are brave warriors, and they wield thick, tough leeks in battle.'),
(84, NULL, 'Doduo', '84.png', 'Twin Bird Pokémon', 'Normal', 'Flying', 'The brains in its two heads appear to communicate emotions to each other with a telepathic power.'),
(85, NULL, 'Dodrio', '85.png', 'Triple Bird Pokémon', 'Normal', 'Flying', 'When Doduo evolves into this odd breed, one of its heads splits into two. This Pokémon runs at nearly 40 mph.'),
(86, NULL, 'Seel', '86.png', 'Sea Lion Pokémon', 'Water', NULL, 'This Pokémon lives on icebergs. It uses the sharp point on its head to break up ice as it swims in the sea.'),
(87, NULL, 'Dewgong', '87.png', 'Sea Lion Pokémon', 'Water', 'Ice', 'In snow, the pure white coat covering its body obscures it from predators.'),
(88, NULL, 'Grimer', '88.png', 'Sludge Pokémon', 'Poison', NULL, 'Born from sludge, these Pokémon now gather in polluted places and increase the bacteria in their bodies.'),
(88, 1, 'Grimer', '88-alola.png', 'Sludge Pokémon', 'Poison', 'Dark', 'It has a passion for trash above all else, speedily digesting it and creating brilliant crystals of sparkling poison.'),
(89, NULL, 'Muk', '89.png', 'Sludge Pokémon', 'Poison', NULL, 'It''s thickly covered with a filthy, vile sludge. It is so toxic, even its footprints contain poison.'),
(89, 1, 'Muk', '89-alola.png', 'Sludge Pokémon', 'Poison', 'Dark', 'What look like fangs and claws are actually crystallized poison that will afflict you at a mere touch, so don''t get too close.'),
(90, NULL, 'Shellder', '90.png', 'Bivalve Pokémon', 'Water', NULL, 'Clamping on to an opponent reveals its vulnerable parts, so it uses this move only as a last resort.'),
(91, NULL, 'Cloyster', '91.png', 'Bivalve Pokémon', 'Water', 'Ice', 'When attacked, it launches its spikes in quick volleys. Its innards have never been seen.'),
(92, NULL, 'Gastly', '92.png', 'Gas Pokémon', 'Ghost', 'Poison', 'Its body is made of gas. Despite lacking substance, it can envelop an opponent of any size and cause suffocation.'),
(93, NULL, 'Haunter', '93.png', 'Gas Pokémon', 'Ghost', 'Poison', 'It likes to lurk in the dark and tap shoulders with a gaseous hand. Its touch causes endless shuddering.'),
(94, NULL, 'Gengar', '94.png', 'Shadow Pokémon', 'Ghost', 'Poison', 'To steal the life of its target, it slips into the prey''s shadow and silently waits for an opportunity.'),
(95, NULL, 'Onix', '95.png', 'Rock Snake Pokémon', 'Rock', 'Ground', 'This chain of immense stones resembles a giant serpent. Tremors shake the earth above as it burrows deep beneath the ground, feeding on boulders as it goes.'),
(96, NULL, 'Drowzee', '96.png', 'Hypnosis Pokémon', 'Psychic', NULL, 'It remembers every dream it eats. It rarely eats the dreams of adults because children''s are much tastier.'),
(97, NULL, 'Hypno', '97.png', 'Hypnosis Pokémon', 'Psychic', NULL, 'Always holding a pendulum that it swings at a steady rhythm, it causes drowsiness in anyone nearby.'),
(98, NULL, 'Krabby', '98.png', 'River Crab Pokémon', 'Water', NULL, 'It lives in burrows dug on sandy beaches. Its pincers fully grow back if they are lost in battle.'),
(99, NULL, 'Kingler', '99.png', 'Pincer Pokémon', 'Water', NULL, 'The larger pincer has 10,000-horsepower strength. However, it is so heavy, it is difficult to aim.'),
(100, NULL, 'Voltorb', '100.png', 'Ball Pokémon', 'Electric', NULL, 'It rolls to move. If the ground is uneven, a sudden jolt from hitting a bump can cause it to explode.'),
(100, 3, 'Voltorb', '100-hisui.png', 'Sphere Pokémon', 'Electric', 'Grass', 'An enigmatic Pokémon that happens to bear a resemblance to a Poké Ball. When excited, it discharges the electric current it has stored in its belly, then lets out a great, uproarious laugh.'),
(101, NULL, 'Electrode', '101.png', 'Ball Pokémon', 'Electric', NULL, 'It explodes in response to even minor stimuli. It is feared, with the nickname of the Bomb Ball.'),
(101, 3, 'Electrode', '101-hisui.png', 'Sphere Pokémon', 'Electric', 'Grass', 'The tissue on the surface of its body is curiously similar in composition to an Apricorn. When irritated, this Pokémon lets loose an electric current equal to 20 lightning bolts.'),
(102, NULL, 'Exeggcute', '102.png', 'Egg Pokémon', 'Grass', 'Psychic', 'Its six eggs converse using telepathy. They can quickly gather if they become separated.'),
(103, NULL, 'Exeggutor', '103.png', 'Coconut Pokémon', 'Grass', 'Psychic', 'It is called the Walking Jungle. If a head grows too big, it falls off and becomes an Exeggcute.'),
(103, 1, 'Exeggutor', '103-alola.png', 'Coconut Pokémon', 'Grass', 'Dragon', 'This Pokémon''s psychic powers aren''t as strong as they once were. The head on this Exeggutor''s tail scans surrounding areas with weak telepathy.'),
(104, NULL, 'Cubone', '104.png', 'Lonely Pokémon', 'Ground', NULL, 'This Pokémon wears the skull of its deceased mother. Sometimes Cubone''s dreams make it cry, but each tear Cubone sheds makes it stronger.'),
(105, NULL, 'Marowak', '105.png', 'Bone Keeper Pokémon', 'Ground', NULL, 'The bones it uses have been in its possession since it was born. It has a ferocious nature.'),
(105, 1, 'Marowak', '105-alola.png', 'Bone Keeper Pokémon', 'Fire', 'Ghost', 'The cursed flames that light up the bone carried by this Pokémon are said to cause both mental and physical pain that will never fade.'),
(106, NULL, 'Hitmonlee', '106.png', 'Kicking Pokémon', 'Fighting', NULL, 'Its legs can stretch to double their length. First-time foes are startled by Hitmonlee''s extensible reach.'),
(107, NULL, 'Hitmonchan', '107.png', 'Punching Pokémon', 'Fighting', NULL, 'When Hitmonchan twists its arm while throwing a punch, the blow will pulverize even concrete. The Pokémon rests after three minutes of fighting.'),
(108, NULL, 'Lickitung', '108.png', 'Licking Pokémon', 'Normal', NULL, 'Wields its long tongue deftly, as though it were an arm. The Pokémon''s viscous saliva, once it has been collected and boiled down, yields a strong and highly useful adhesive.'),
(109, NULL, 'Koffing', '109.png', 'Poison Gas Pokémon', 'Poison', NULL, 'Toxic gas is held within its thin, balloon-shaped body, so it can cause massive explosions.'),
(110, NULL, 'Weezing', '110.png', 'Poison Gas Pokémon', 'Poison', NULL, 'It grows by feeding on gases released by garbage. Though very rare, triplets have been found.'),
(110, 2, 'Weezing', '110-galar.png', 'Poison Gas Pokémon', 'Poison', 'Fairy', 'Long ago, during a time when droves of factories fouled the air with pollution, Weezing changed into this form for some reason.'),
(111, NULL, 'Rhyhorn', '111.png', 'Spikes Pokémon', 'Ground', 'Rock', 'Ludicrously strong—when it butts heads with a mountain, it is the mountain that shatters. But its short legs struggle with turns, and it is incapable of stopping unless it collides with something.'),
(112, NULL, 'Rhydon', '112.png', 'Drill Pokémon', 'Ground', 'Rock', 'Rapidly rotates its horn to bore through bedrock. It swaggers around volcanic regions, protected from the lava''s heat by its tough, armorlike hide.'),
(113, NULL, 'Chansey', '113.png', 'Egg Pokémon', 'Normal', NULL, 'This kindly Pokémon lays highly nutritious eggs and shares them with injured Pokémon or people.'),
(114, NULL, 'Tangela', '114.png', 'Vine Pokémon', 'Grass', NULL, 'It is cloaked entirely in blue vines, preventing any glimpse of its true identity. The vines impart a refreshing sensation when chewed—they''re useful as a spice.'),
(115, NULL, 'Kangaskhan', '115.png', 'Parent Pokémon', 'Normal', NULL, 'It raises its offspring in its belly pouch. It lets its baby out to play only when it feels safe to do so.'),
(116, NULL, 'Horsea', '116.png', 'Dragon Pokémon', 'Water', NULL, 'It makes its nest in the shade of corals. If it senses danger, it spits black ink and flees.'),
(117, NULL, 'Seadra', '117.png', 'Dragon Pokémon', 'Water', NULL, 'Its spines provide protection. Its fins and bones are prized as traditional medicine ingredients.'),
(118, NULL, 'Goldeen', '118.png', 'Goldfish Pokémon', 'Water', NULL, 'It swims at a steady five knots. If it senses danger, it will strike back with its sharp horn.'),
(119, NULL, 'Seaking', '119.png', 'Goldfish Pokémon', 'Water', NULL, 'To protect its family, it will fight with its drill-sharp horn. It lives in hollowed rocks in streams.'),
(120, NULL, 'Staryu', '120.png', 'Star Shape Pokémon', 'Water', NULL, 'If Staryu''s body is damaged, it will regenerate as long as the red core remains. The core flashes at midnight.'),
(121, NULL, 'Starmie', '121.png', 'Mysterious Pokémon', 'Water', NULL, 'At the center of its body is a red core that sends mysterious radio signals into the night sky.'),
(122, NULL, 'Mr. Mime', '122.png', 'Barrier Pokémon', 'Psychic', 'Fairy', 'The behavior of this clown-like Pokémon reminds one of pantomime. It creates invisible walls using a force emitted from its fingertips.'),
(122, 2, 'Mr. Mime', '122-galar.png', 'Dancing Pokémon', 'Ice', 'Psychic', 'Its talent is tap-dancing. It can also manipulate temperatures to create a floor of ice, which this Pokémon can kick up to use as a barrier.'),
(123, NULL, 'Scyther', '123.png', 'Mantis Pokémon', 'Bug', 'Flying', 'The sharp scythes on its forearms become increasingly sharp by cutting through hard objects.'),
(124, NULL, 'Jynx', '124.png', 'Human Shape Pokémon', 'Ice', 'Psychic', 'Its cries sound like human speech. However, it is impossible to tell what it is trying to say.'),
(125, NULL, 'Electabuzz', '125.png', 'Electric Pokémon', 'Electric', NULL, 'Feeds on electrical energy. During sudden showers beneath looming thunderclouds, one can observe Electabuzz scaling tall trees, where the Pokémon will then wait for lightning to strike.'),
(126, NULL, 'Magmar', '126.png', 'Spitfire Pokémon', 'Fire', NULL, 'Legend has it that this Pokémon was born from the crater of a volcano. When wounded, it bathes in lava to heal its body, much as one would soak in a hot spring.'),
(127, NULL, 'Pinsir', '127.png', 'Stag Beetle Pokémon', 'Bug', NULL, 'It grips prey with its pincers until the prey is torn apart. What it can''t tear, it tosses far away.'),
(128, NULL, 'Tauros', '128.png', 'Wild Bull Pokémon', 'Normal', NULL, 'When it targets an enemy, it charges furiously while whipping its body with its long tails.'),
(128, 4, 'Tauros', '128-paldea.png', 'Wild Bull Pokémon', 'Fighting', NULL, 'This kind of Tauros, known as the Combat Breed, is distinguished by its thick, powerful muscles and its fierce disposition.'),
(129, NULL, 'Magikarp', '129.png', 'Fish Pokémon', 'Water', NULL, 'An underpowered, pathetic Pokémon. It may jump high on rare occasions but never more than seven feet.'),
(130, NULL, 'Gyarados', '130.png', 'Atrocious Pokémon', 'Water', 'Flying', 'Once it appears, it goes on a rampage. It remains enraged until it demolishes everything around it.'),
(131, NULL, 'Lapras', '131.png', 'Transport Pokémon', 'Water', 'Ice', 'It loves crossing the sea with people and Pokémon on its back. It understands human speech.'),
(132, NULL, 'Ditto', '132.png', 'Transform Pokémon', 'Normal', NULL, 'It can freely recombine its own cellular structure to transform into other life-forms.'),
(133, NULL, 'Eevee', '133.png', 'Evolution Pokémon', 'Normal', NULL, 'Its ability to evolve into many forms allows it to adapt smoothly and perfectly to any environment.'),
(134, NULL, 'Vaporeon', '134.png', 'Bubble Jet Pokémon', 'Water', NULL, 'Its cell composition is similar to water molecules. As a result, it can''t be seen when it melts away into water.'),
(135, NULL, 'Jolteon', '135.png', 'Lightning Pokémon', 'Electric', NULL, 'If agitated, it uses electricity to straighten out its fur and launch it in small bunches.'),
(136, NULL, 'Flareon', '136.png', 'Flame Pokémon', 'Fire', NULL, 'Inhaled air is carried to its flame sac, heated, and exhaled as fire that reaches over 3,000 degrees Fahrenheit.'),
(137, NULL, 'Porygon', '137.png', 'Virtual Pokémon', 'Normal', NULL, 'The world''s first artificially created Pokémon. It can travel through electronic space.'),
(138, NULL, 'Omanyte', '138.png', 'Spiral Pokémon', 'Rock', 'Water', 'It''s a Pokémon that was resurrected from a fossil using modern science. It swam in ancient seas.'),
(139, NULL, 'Omastar', '139.png', 'Spiral Pokémon', 'Rock', 'Water', 'It is thought that this Pokémon became extinct because its spiral shell grew too large.'),
(140, NULL, 'Kabuto', '140.png', 'Shellfish Pokémon', 'Rock', 'Water', 'It is thought to have inhabited beaches 300 million years ago. It is protected by a sturdy shell.'),
(141, NULL, 'Kabutops', '141.png', 'Shellfish Pokémon', 'Rock', 'Water', 'It is thought that this Pokémon came onto land because its prey adapted to life on land.'),
(142, NULL, 'Aerodactyl', '142.png', 'Fossil Pokémon', 'Rock', 'Flying', 'It''s a Pokémon that roamed the skies in the dinosaur era. Its teeth are like saw blades.'),
(143, NULL, 'Snorlax', '143.png', 'Sleeping Pokémon', 'Normal', NULL, 'This glutton appears in villages without warning and devours the entirety of their rice granaries—such occurrences have long been counted among the gravest of disasters.'),
(144, NULL, 'Articuno', '144.png', 'Freeze Pokémon', 'Ice', 'Flying', 'This legendary bird Pokémon can create blizzards by freezing moisture in the air.'),
(144, 2, 'Articuno', '144-galar.png', 'Cruel Pokémon', 'Psychic', 'Flying', 'Known as Articuno, this Pokémon fires beams that can immobilize opponents as if they had been frozen solid.'),
(145, NULL, 'Zapdos', '145.png', 'Electric Pokémon', 'Electric', 'Flying', 'This legendary Pokémon is said to live in thunderclouds. It freely controls lightning bolts.'),
(145, 2, 'Zapdos', '145-galar.png', 'Strong Legs Pokémon', 'Fighting', 'Flying', 'One kick from its powerful legs will pulverize a dump truck. Supposedly, this Pokémon runs through the mountains at over 180 mph.'),
(146, NULL, 'Moltres', '146.png', 'Flame Pokémon', 'Fire', 'Flying', 'It is one of the legendary bird Pokémon. Its appearance is said to indicate the coming of spring.'),
(146, 2, 'Moltres', '146-galar.png', 'Malevolent Pokémon', 'Dark', 'Flying', 'This Pokémon''s sinister, flame-like aura will consume the spirit of any creature it hits. Victims become burned-out shadows of themselves.'),
(147, NULL, 'Dratini', '147.png', 'Dragon Pokémon', 'Dragon', NULL, 'It is born large to start with. It repeatedly sheds its skin as it steadily grows longer.'),
(148, NULL, 'Dragonair', '148.png', 'Dragon Pokémon', 'Dragon', NULL, 'It is called the divine Pokémon. When its entire body brightens slightly, the weather changes.'),
(149, NULL, 'Dragonite', '149.png', 'Dragon Pokémon', 'Dragon', 'Flying', 'It can fly in spite of its big and bulky physique. It circles the globe in just 16 hours.'),
(150, NULL, 'Mewtwo', '150.png', 'Genetic Pokémon', 'Psychic', NULL, 'Mewtwo was created by recombining Mew''s genes. It''s said to have the most savage heart among Pokémon.'),
(151, NULL, 'Mew', '151.png', 'New Species Pokémon', 'Psychic', NULL, 'Because it can use all kinds of moves, many scientists believe Mew to be the ancestor of Pokémon.'),
(152, NULL, 'Chikorita', '152.png', 'Leaf Pokémon', 'Grass', NULL, 'It uses the leaf on its head to determine the air''s temperature and humidity. It loves to sunbathe.'),
(153, NULL, 'Bayleef', '153.png', 'Leaf Pokémon', 'Grass', NULL, 'The buds that ring its neck give off a spicy aroma that perks people up.'),
(154, NULL, 'Meganium', '154.png', 'Herb Pokémon', 'Grass', NULL, 'Its breath has the fantastic ability to revive dead plants and flowers.'),
(155, NULL, 'Cyndaquil', '155.png', 'Fire Mouse Pokémon', 'Fire', NULL, 'It has a timid nature. If it is startled, the flames on its back burn more vigorously.'),
(156, NULL, 'Quilava', '156.png', 'Volcano Pokémon', 'Fire', NULL, 'It intimidates foes with the heat of its flames. The fire burns stronger as it prepares to fight.'),
(157, NULL, 'Typhlosion', '157.png', 'Volcano Pokémon', 'Fire', NULL, 'It attacks using blasts of fire. It creates heat shimmers with intense fire to hide itself.'),
(157, 3, 'Typhlosion', '157-hisui.png', 'Ghost Flame Pokémon', 'Fire', 'Ghost', 'Said to purify lost, forsaken souls with its flames and guide them to the afterlife. I believe its form has been influenced by the energy of the sacred mountain towering at Hisui''s center.'),
(158, NULL, 'Totodile', '158.png', 'Big Jaw Pokémon', 'Water', NULL, 'It has a habit of biting everything with its well-developed jaws. Even its Trainer needs to be careful.'),
(159, NULL, 'Croconaw', '159.png', 'Big Jaw Pokémon', 'Water', NULL, 'Once it bites down, it won''t let go until it loses its fangs. New fangs quickly grow into place.'),
(160, NULL, 'Feraligatr', '160.png', 'Big Jaw Pokémon', 'Water', NULL, 'It usually moves slowly, but it goes at blinding speed when it attacks and bites prey.'),
(161, NULL, 'Sentret', '161.png', 'Scout Pokémon', 'Normal', NULL, 'It has a very nervous nature. It stands up high on its tail so it can scan wide areas.'),
(162, NULL, 'Furret', '162.png', 'Long Body Pokémon', 'Normal', NULL, 'The mother puts its offspring to sleep by curling up around them. It corners foes with speed.'),
(163, NULL, 'Hoothoot', '163.png', 'Owl Pokémon', 'Normal', 'Flying', 'It switches its standing foot so quickly that the switch can''t be seen. It cries at the same time every day.'),
(164, NULL, 'Noctowl', '164.png', 'Owl Pokémon', 'Normal', 'Flying', 'If it flips its head upside down, it''s a sign that it is engaged in very complex thinking.'),
(165, NULL, 'Ledyba', '165.png', 'Five Star Pokémon', 'Bug', 'Flying', 'It''s so timid that it can''t move unless it''s with a swarm. It conveys its feelings through scent.'),
(166, NULL, 'Ledian', '166.png', 'Five Star Pokémon', 'Bug', 'Flying', 'It uses starlight as energy. When more stars appear at night, the patterns on its back grow larger.'),
(167, NULL, 'Spinarak', '167.png', 'String Spit Pokémon', 'Bug', 'Poison', 'It sets a trap by spinning a web with thin but strong thread. It waits motionlessly for prey to arrive.'),
(168, NULL, 'Ariados', '168.png', 'Long Leg Pokémon', 'Bug', 'Poison', 'It attaches silk to its prey and sets it free. Later, it tracks the silk to the prey and its friends.'),
(169, NULL, 'Crobat', '169.png', 'Bat Pokémon', 'Poison', 'Flying', 'Its hind limbs have become another set of wings. Crobat expertly maneuvers its four wings to dart in exquisite fashion through even the most confined caves without losing any speed.'),
(170, NULL, 'Chinchou', '170.png', 'Angler Pokémon', 'Water', 'Electric', 'It discharges positive and negative electricity from the tips of its antennae to shock its foes.'),
(171, NULL, 'Lanturn', '171.png', 'Light Pokémon', 'Water', 'Electric', 'Lanturn''s light can shine up from great depths. It is nicknamed the Deep-Sea Star.'),
(172, NULL, 'Pichu', '172.png', 'Tiny Mouse Pokémon', 'Electric', NULL, 'Despite this Pokémon''s cute appearance, those who want to live with one should prepare to be on the receiving end of its electric jolts.'),
(173, NULL, 'Cleffa', '173.png', 'Star Shape Pokémon', 'Fairy', NULL, 'In silhouette, they resemble twinkling starlight. When shooting stars rain from the night sky, Cleffa gather in numbers and dance as though they are indeed incarnations of the stars.'),
(174, NULL, 'Igglybuff', '174.png', 'Balloon Pokémon', 'Normal', 'Fairy', 'It likes to sing but is not yet good at it. With praise and encouragement, it will get better little by little.'),
(175, NULL, 'Togepi', '175.png', 'Spike Ball Pokémon', 'Fairy', NULL, 'This ovate creature is frequently mistaken for a moving egg when encountered out in the fields or in the mountains. Its guileless smile soothes the soul.'),
(176, NULL, 'Togetic', '176.png', 'Happiness Pokémon', 'Fairy', 'Flying', 'No records exist of Togetic being seen in the wilds. Rumors abound that it evolves under the loving care of a trusted human companion, upon whom the Pokémon then bestows great joy.'),
(177, NULL, 'Natu', '177.png', 'Tiny Bird Pokémon', 'Psychic', 'Flying', 'It picks food from cactus plants, deftly avoiding buds and spines. It seems to skip about to move.'),
(178, NULL, 'Xatu', '178.png', 'Mystic Pokémon', 'Psychic', 'Flying', 'This odd Pokémon can see both the past and the future. It eyes the sun''s movement all day.'),
(179, NULL, 'Mareep', '179.png', 'Wool Pokémon', 'Electric', NULL, 'If static electricity builds in its body, its fleece doubles in volume. Touching it will shock you.'),
(180, NULL, 'Flaaffy', '180.png', 'Wool Pokémon', 'Electric', NULL, 'As a result of storing too much electricity, it developed patches where even downy wool won''t grow.'),
(181, NULL, 'Ampharos', '181.png', 'Light Pokémon', 'Electric', NULL, 'When it gets dark, the light from its bright, shiny tail can be seen from far away on the ocean''s surface.'),
(182, NULL, 'Bellossom', '182.png', 'Flower Pokémon', 'Grass', NULL, 'When the heavy rainfall season ends, it is drawn out by warm sunlight to dance in the open.'),
(183, NULL, 'Marill', '183.png', 'Aqua Mouse Pokémon', 'Water', 'Fairy', 'The fur on its body naturally repels water. It can stay dry even when it plays in the water.'),
(184, NULL, 'Azumarill', '184.png', 'Aqua Rabbit Pokémon', 'Water', 'Fairy', 'Its long ears are superb sensors. It can distinguish the movements of things in water and tell what they are.'),
(185, NULL, 'Sudowoodo', '185.png', 'Imitation Pokémon', 'Rock', NULL, 'To avoid being attacked, it does nothing but mimic a tree. It hates water and flees from rain.'),
(186, NULL, 'Politoed', '186.png', 'Frog Pokémon', 'Water', NULL, 'A group of Poliwag and Poliwhirl will form with a Politoed as the leader. Politoed''s cries make the Pokémon of the group obey.'),
(187, NULL, 'Hoppip', '187.png', 'Cottonweed Pokémon', 'Grass', 'Flying', 'Outside of cold regions, Hoppip can be found practically everywhere. This is because the wind carries this species all over the world.'),
(188, NULL, 'Skiploom', '188.png', 'Cottonweed Pokémon', 'Grass', 'Flying', 'When the weather grows cold, Skiploom''s flower closes and the Pokémon cannot photosynthesize, so it flies away to warmer regions.'),
(189, NULL, 'Jumpluff', '189.png', 'Cottonweed Pokémon', 'Grass', 'Flying', 'Beware its cotton spores. If you accidentally breathe them in, you''ll be racked with coughs and itchiness.'),
(190, NULL, 'Aipom', '190.png', 'Long Tail Pokémon', 'Normal', NULL, 'This treetop dweller possesses a tail as dexterous as a hand. Ancient writings describe this Pokémon as a one-armed oddity.'),
(191, NULL, 'Sunkern', '191.png', 'Seed Pokémon', 'Grass', NULL, 'It is very weak. Its only means of defense is to shake its leaves desperately at its attacker.'),
(192, NULL, 'Sunflora', '192.png', 'Sun Pokémon', 'Grass', NULL, 'Since it converts sunlight into energy, it is always looking in the direction of the sun.'),
(193, NULL, 'Yanma', '193.png', 'Clear Wing Pokémon', 'Bug', 'Flying', 'Its frail wings are so thin that one can see clear through them. However, during flight these wings exhibit the power to churn air with force enough to launch a house skyward.'),
(194, NULL, 'Wooper', '194.png', 'Water Fish Pokémon', 'Water', 'Ground', 'When the temperature cools in the evening, they emerge from water to seek food along the shore.'),
(194, 4, 'Wooper', '194-paldea.png', 'Poison Fish Pokémon', 'Poison', 'Ground', 'After losing a territorial struggle, Wooper began living on land. The Pokémon changed over time, developing a poisonous film to protect its body.'),
(195, NULL, 'Quagsire', '195.png', 'Water Fish Pokémon', 'Water', 'Ground', 'A dim-witted Pokémon. It doesn''t care if it bumps its head into boats or rocks while swimming.'),
(196, NULL, 'Espeon', '196.png', 'Sun Pokémon', 'Psychic', NULL, 'The tip of its forked tail quivers when it is predicting its opponent''s next move.'),
(197, NULL, 'Umbreon', '197.png', 'Moon Pokémon', 'Dark', NULL, 'When exposed to the moon''s aura, the rings on its body glow faintly and it gains a mysterious power.'),
(198, NULL, 'Murkrow', '198.png', 'Darkness Pokémon', 'Dark', 'Flying', 'If spotted, it will lure an unwary person into chasing it, then lose the pursuer on mountain trails.'),
(199, NULL, 'Slowking', '199.png', 'Royal Pokémon', 'Water', 'Psychic', 'Being bitten by Shellder gave it intelligence comparable to that of internationally recognized scientists.'),
(199, 2, 'Slowking', '199-galar.png', 'Hexpert Pokémon', 'Poison', 'Psychic', 'A combination of toxins and the shock of evolving has increased Shellder''s intelligence to the point that Shellder now controls Slowking.'),
(200, NULL, 'Misdreavus', '200.png', 'Screech Pokémon', 'Ghost', NULL, 'It loves to bite and yank people''s hair from behind without warning, just to see their shocked reactions.'),
(201, NULL, 'Unown', '201.png', 'Symbol Pokémon', 'Psychic', NULL, 'Because the Pokémon is shaped like ancient writing, it is a huge mystery whether written language or Unown came first.'),
(202, NULL, 'Wobbuffet', '202.png', 'Patient Pokémon', 'Psychic', NULL, 'It desperately tries to keep its black tail hidden. This behavior is said to be proof that its tail hides a secret.'),
(203, NULL, 'Girafarig', '203.png', 'Long Neck Pokémon', 'Normal', 'Psychic', 'Girafarig''s tail has a small head. It instinctively bites at any foe that approaches the Pokémon from behind.'),
(204, NULL, 'Pineco', '204.png', 'Bagworm Pokémon', 'Bug', NULL, 'It spits out a fluid that it uses to glue tree bark to its body. The fluid hardens when it touches air.'),
(205, NULL, 'Forretress', '205.png', 'Bagworm Pokémon', 'Bug', 'Steel', 'Its entire body is shielded by a steel-hard shell. What lurks inside this shell is a total mystery.'),
(206, NULL, 'Dunsparce', '206.png', 'Land Snake Pokémon', 'Normal', NULL, 'If spotted, it escapes by burrowing with its tail. It can float just slightly using its wings.'),
(207, NULL, 'Gligar', '207.png', 'Fly Scorpion Pokémon', 'Ground', 'Flying', 'Its tail is tipped by a thick, horrible stinger. To bring down prey, it will first obscure their vision by covering their faces with its body, and then it will use the stinger to inject them with venom.'),
(208, NULL, 'Steelix', '208.png', 'Iron Snake Pokémon', 'Steel', 'Ground', 'This Pokémon evolved through use of a strange item. Its body is coated with steel powder and notably hard—not even diamond can leave so much as a scratch.'),
(209, NULL, 'Snubbull', '209.png', 'Fairy Pokémon', 'Fairy', NULL, 'Small Pokémon flee from its scary face. It is, however, considered by many people to be cute.'),
(210, NULL, 'Granbull', '210.png', 'Fairy Pokémon', 'Fairy', NULL, 'It is timid in spite of its looks. If it becomes enraged, however, it will strike with its huge fangs.'),
(211, NULL, 'Qwilfish', '211.png', 'Balloon Pokémon', 'Water', 'Poison', 'Be cautious if this Pokémon starts sucking in water—it will soon attack by scattering the toxic spikes that grow all over its body.'),
(211, 3, 'Qwilfish', '211.png', 'Balloon Pokémon', 'Dark', 'Poison', 'Fishers detest this troublesome Pokémon because it sprays poison from its spines, getting it everywhere. A different form of Qwilfish lives in other regions.'),
(212, NULL, 'Scizor', '212.png', 'Pincer Pokémon', 'Bug', 'Steel', 'This Pokémon''s pincers, which contain steel, can crush any hard object they get ahold of into bits.'),
(213, NULL, 'Shuckle', '213.png', 'Mold Pokémon', 'Bug', 'Rock', 'It stores berries in its shell. The berries mix with its body fluids to become delicious juices.'),
(214, NULL, 'Heracross', '214.png', 'Single Horn Pokémon', 'Bug', 'Fighting', 'With its herculean powers, it can easily throw around an object that is 100 times its own weight.'),
(215, NULL, 'Sneasel', '215.png', 'Sharp Claw Pokémon', 'Dark', 'Ice', 'This is a smart and sneaky Pokémon. A pair may work together to steal eggs by having one lure the parents away.'),
(215, 3, 'Sneasel', '215.png', 'Sharp Claw Pokémon', 'Fighting', 'Poison', 'Its sturdy, curved claws are ideal for traversing precipitous cliffs. From the tips of these claws drips a venom that infiltrates the nerves of any prey caught in Sneasel''s grasp.'),
(216, NULL, 'Teddiursa', '216.png', 'Little Bear Pokémon', 'Normal', NULL, 'Its paws are soaked in oodles of honey. When nervous, Teddiursa will lick its paws and soon have a smile back on its face.'),
(217, NULL, 'Ursaring', '217.png', 'Hibernator Pokémon', 'Normal', NULL, 'It usually wears a hardened expression, but when it''s licking up honey—which it loves—the joy it feels will cause it to break into a wide grin.'),
(218, NULL, 'Slugma', '218.png', 'Lava Pokémon', 'Fire', NULL, 'Its body is made of magma. If it doesn''t keep moving, its body will cool and harden.'),
(219, NULL, 'Magcargo', '219.png', 'Lava Pokémon', 'Fire', 'Rock', 'Its body temperature is roughly 18,000 degrees Fahrenheit. Flames burst from gaps in its shell made of hardened magma.'),
(220, NULL, 'Swinub', '220.png', 'Pig Pokémon', 'Ice', 'Ground', 'It loves eating mushrooms that grow under dead grass. It also finds hot springs while foraging.'),
(221, NULL, 'Piloswine', '221.png', 'Swine Pokémon', 'Ice', 'Ground', 'The long fur of this Pokémon covers its eyes, ears, and even limbs, allowing Piloswine to resist harshly frigid conditions. The Pokémon''s white tusks can be used to defeat its enemies.'),
(222, NULL, 'Corsola', '222.png', 'Coral Pokémon', 'Water', 'Rock', 'Many live in the clean seas of the south. They apparently can''t live in polluted waters.'),
(222, 2, 'Corsola', '222-galar.png', 'Coral Pokémon', 'Ghost', NULL, 'Watch your step when wandering areas oceans once covered. What looks like a stone could be this Pokémon, and it will curse you if you kick it.'),
(223, NULL, 'Remoraid', '223.png', 'Jet Pokémon', 'Water', NULL, 'Spits water from its mouth with incredible accuracy. It captures Burmy by shooting them down off the branches from which they dangle.'),
(224, NULL, 'Octillery', '224.png', 'Jet Pokémon', 'Water', NULL, 'While Octillery still shoots water from its mouth, the drastic anatomical difference between it and Remoraid meant that for a long time, no one believed the former evolved from the latter.'),
(225, NULL, 'Delibird', '225.png', 'Delivery Pokémon', 'Ice', 'Flying', 'It always carries its food with it, wherever it goes. If attacked, it throws its food at the opponent.'),
(226, NULL, 'Mantine', '226.png', 'Kite Pokémon', 'Water', 'Flying', 'This calm and gentle Pokémon swims gracefully through the sea. After building speed, it can leap out of the water. It is often misidentified as a bird Pokémon due to this behavior.'),
(227, NULL, 'Skarmory', '227.png', 'Armor Bird Pokémon', 'Steel', 'Flying', 'Skarmory is clad entirely in ironhard armor. It flies at speeds over 180 mph.'),
(228, NULL, 'Houndour', '228.png', 'Dark Pokémon', 'Dark', 'Fire', 'It uses different kinds of cries for communicating with others of its kind and for pursuing its prey.'),
(229, NULL, 'Houndoom', '229.png', 'Dark Pokémon', 'Dark', 'Fire', 'If you are burned by the flames it shoots from its mouth, the pain will never go away.'),
(230, NULL, 'Kingdra', '230.png', 'Dragon Pokémon', 'Water', 'Dragon', 'It lives in caves on the seafloor and creates giant whirlpools every time it moves.'),
(231, NULL, 'Phanpy', '231.png', 'Long Nose Pokémon', 'Ground', NULL, 'It is far stronger than it appears. If a Phanpy is swinging its trunk around and your arm gets hit by it, your arm bone will shatter.'),
(232, NULL, 'Donphan', '232.png', 'Armor Pokémon', 'Ground', NULL, 'Donphan is normally a calm Pokémon, but once it is enraged, it will curl its body into a ball and charge at you while rolling.'),
(233, NULL, 'Porygon2', '233.png', 'Virtual Pokémon', 'Normal', NULL, 'After artificial intelligence was implemented in Porygon2, the Pokémon began using a strange language that only other Porygon2 understand.'),
(234, NULL, 'Stantler', '234.png', 'Big Horn Pokémon', 'Normal', NULL, 'It''s said that this Pokémon used to be stronger long ago when it had many enemies, and that it was even able to evolve under its own power.'),
(235, NULL, 'Smeargle', '235.png', 'Painter Pokémon', 'Normal', NULL, 'It marks its territory by using its tail like a paintbrush. There are more than 5,000 different marks.'),
(236, NULL, 'Tyrogue', '236.png', 'Scuffle Pokémon', 'Fighting', NULL, 'It is famous for its eagerness to fight and always nurses injuries from challenging larger foes.'),
(237, NULL, 'Hitmontop', '237.png', 'Handstand Pokémon', 'Fighting', NULL, 'It fights while spinning like a top. The centrifugal force boosts its destructive power by a factor of 10.'),
(238, NULL, 'Smoochum', '238.png', 'Kiss Pokémon', 'Ice', 'Psychic', 'It tests everything by touching with its lips, which remember what it likes and dislikes.'),
(239, NULL, 'Elekid', '239.png', 'Electric Pokémon', 'Electric', NULL, 'They generate electricity by spinning their arms. During a thunderstorm, if one hears the lively voices of children out in the wilderness, what one is actually hearing are the voices of Elekid.'),
(240, NULL, 'Magby', '240.png', 'Live Coal Pokémon', 'Fire', NULL, 'This Pokémon lives in volcanic areas. With each breath, sparks spurt from its mouth and nose. When Magby is in good health, its flames gain a yellow tint.'),
(241, NULL, 'Miltank', '241.png', 'Milk Cow Pokémon', 'Normal', NULL, 'It is said that kids who drink Miltank''s milk grow up to become hearty, healthy adults.'),
(242, NULL, 'Blissey', '242.png', 'Happiness Pokémon', 'Normal', NULL, 'Anyone who takes even one taste of Blissey''s egg becomes unfailingly caring and pleasant to everyone.'),
(243, NULL, 'Raikou', '243.png', 'Thunder Pokémon', 'Electric', NULL, 'It is said to have fallen with lightning. It can fire thunderbolts from the rain clouds on its back.'),
(244, NULL, 'Entei', '244.png', 'Volcano Pokémon', 'Fire', NULL, 'It is said that when it roars, a volcano erupts somewhere around the globe.'),
(245, NULL, 'Suicune', '245.png', 'Aurora Pokémon', 'Water', NULL, 'It races around the world to purify fouled water. It dashes away with the north wind.'),
(246, NULL, 'Larvitar', '246.png', 'Rock Skin Pokémon', 'Rock', 'Ground', 'It is born deep underground. It can''t emerge until it has entirely consumed the soil around it.'),
(247, NULL, 'Pupitar', '247.png', 'Hard Shell Pokémon', 'Rock', 'Ground', 'Its shell is as hard as bedrock, and it is also very strong. Its thrashing can topple a mountain.'),
(248, NULL, 'Tyranitar', '248.png', 'Armor Pokémon', 'Rock', 'Dark', 'Extremely strong, it can change the landscape. It is so insolent that it doesn''t care about others.'),
(249, NULL, 'Lugia', '249.png', 'Diving Pokémon', 'Psychic', 'Flying', 'It sleeps in a deep-sea trench. If it flaps its wings, it is said to cause a 40-day storm.'),
(250, NULL, 'Ho-oh', '250.png', 'Rainbow Pokémon', 'Fire', 'Flying', 'Its feathers are in seven colors. It is said that anyone seeing it is promised eternal happiness.'),
(251, NULL, 'Celebi', '251.png', 'Time Travel Pokémon', 'Psychic', 'Grass', 'It has the power to travel across time, but it is said to appear only in peaceful times.'),
(252, NULL, 'Treecko', '252.png', 'Wood Gecko Pokémon', 'Grass', NULL, 'The soles of its feet are covered by countless tiny hooks, enabling it to walk on walls and ceilings.'),
(253, NULL, 'Grovyle', '253.png', 'Wood Gecko Pokémon', 'Grass', NULL, 'It lives in dense jungles. While closing in on its prey, it leaps from branch to branch.'),
(254, NULL, 'Sceptile', '254.png', 'Forest Pokémon', 'Grass', NULL, 'The leaves that grow on its arms can slice down thick trees. It is without peer in jungle combat.'),
(255, NULL, 'Torchic', '255.png', 'Chick Pokémon', 'Fire', NULL, 'A fire burns inside it, so it feels very warm to hug. It launches fireballs of 1,800 degrees Fahrenheit.'),
(256, NULL, 'Combusken', '256.png', 'Young Fowl Pokémon', 'Fire', 'Fighting', 'Its kicking mastery lets it loose 10 kicks per second. It emits sharp cries to intimidate foes.'),
(257, NULL, 'Blaziken', '257.png', 'Blaze Pokémon', 'Fire', 'Fighting', 'Flames spout from its wrists, enveloping its knuckles. Its punches scorch its foes.'),
(258, NULL, 'Mudkip', '258.png', 'Mud Fish Pokémon', 'Water', NULL, 'Using the fin on its head, Mudkip senses the flow of water to keep track of what''s going on around it. Mudkip has the strength to heft boulders.'),
(259, NULL, 'Marshtomp', '259.png', 'Mud Fish Pokémon', 'Water', 'Ground', 'Its sturdy legs give it sure footing, even in mud. It burrows into dirt to sleep.'),
(260, NULL, 'Swampert', '260.png', 'Mud Fish Pokémon', 'Water', 'Ground', 'It can swim while towing a large ship. It bashes down foes with a swing of its thick arms.'),
(261, NULL, 'Poochyena', '261.png', 'Bite Pokémon', 'Dark', NULL, 'A Pokémon with a persistent nature, it chases its chosen prey until the prey becomes exhausted.'),
(262, NULL, 'Mightyena', '262.png', 'Bite Pokémon', 'Dark', NULL, 'It chases down prey in a pack. It will never disobey the commands of a skilled Trainer.'),
(263, NULL, 'Zigzagoon', '263.png', 'Tiny Raccoon Pokémon', 'Normal', NULL, 'It walks in zigzag fashion. It''s good at finding items in the grass and even in the ground.'),
(263, 2, 'Zigzagoon', '263-galar.png', 'Tiny Raccoon Pokémon', 'Dark', 'Normal', 'Thought to be the oldest form of Zigzagoon, it moves in zigzags and wreaks havoc upon its surroundings.'),
(264, NULL, 'Linoone', '264.png', 'Rushing Pokémon', 'Normal', NULL, 'It charges prey at speeds over 60 mph. However, because it can only run straight, it often fails.'),
(264, 2, 'Linoone', '264-galar.png', 'Rushing Pokémon', 'Dark', 'Normal', 'It uses its long tongue to taunt opponents. Once the opposition is enraged, this Pokémon hurls itself at the opponent, tackling them forcefully.'),
(265, NULL, 'Wurmple', '265.png', 'Worm Pokémon', 'Bug', NULL, 'Likes sap and is abundant in the wild. Why it evolves into various different forms is unknown. One cannot tell from a Wurmple''s appearance which form it will take when it evolves.'),
(266, NULL, 'Silcoon', '266.png', 'Cocoon Pokémon', 'Bug', NULL, 'Wraps itself in thin strings of silk while it stores energy for evolution. It can''t extend its limbs and its movement is slow, but its eyes keep a sharp lookout—Silcoon is always on guard.'),
(267, NULL, 'Beautifly', '267.png', 'Butterfly Pokémon', 'Bug', 'Flying', 'A colorful and incredibly beautiful but also greedy Pokémon. In an effort to keep its favorite food all to itself, it will chase away Combee as they try to gather nectar.'),
(268, NULL, 'Cascoon', '268.png', 'Cocoon Pokémon', 'Bug', NULL, 'The silk coating its body is thin but sufficiently strong. Cascoon''s silk has a luster and texture superior to that of Silcoon''s, and clothes made using Cascoon silk are regarded as top-notch.'),
(269, NULL, 'Dustox', '269.png', 'Poison Moth Pokémon', 'Bug', 'Poison', 'It violently flutters its wings to scatter toxic dust when attacked. It becomes active after sunset.'),
(270, NULL, 'Lotad', '270.png', 'Water Weed Pokémon', 'Water', 'Grass', 'It looks like an aquatic plant and serves as a ferry for Pokémon that can''t swim.'),
(271, NULL, 'Lombre', '271.png', 'Jolly Pokémon', 'Water', 'Grass', 'It has a mischievous spirit. If it spots an angler, it will tug on the fishing line to interfere.'),
(272, NULL, 'Ludicolo', '272.png', 'Carefree Pokémon', 'Water', 'Grass', 'If it hears festive music, all its muscles fill with energy. It can''t help breaking out into a dance.'),
(273, NULL, 'Seedot', '273.png', 'Acorn Pokémon', 'Grass', NULL, 'When it dangles from a tree branch, it looks just like an acorn. It enjoys scaring other Pokémon that try to peck at it.'),
(274, NULL, 'Nuzleaf', '274.png', 'Wily Pokémon', 'Grass', 'Dark', 'The sound of its grass flute makes its listeners uneasy. It lives deep in the forest.'),
(275, NULL, 'Shiftry', '275.png', 'Wicked Pokémon', 'Grass', 'Dark', 'By flapping its leafy fans, it can whip up gusts of 100 feet per second that can level houses.'),
(276, NULL, 'Taillow', '276.png', 'Tiny Swallow Pokémon', 'Normal', 'Flying', 'It has a gutsy spirit that makes it bravely take on tough foes. It flies in search of warm climates.'),
(277, NULL, 'Swellow', '277.png', 'Swallow Pokémon', 'Normal', 'Flying', 'It circles the sky in search of prey and dives sharply to catch its target.'),
(278, NULL, 'Wingull', '278.png', 'Seagull Pokémon', 'Water', 'Flying', 'It soars high in the sky, riding on updrafts like a glider. It carries food tucked in its bill.'),
(279, NULL, 'Pelipper', '279.png', 'Water Bird Pokémon', 'Water', 'Flying', 'It protects its young in its beak. It bobs on waves, resting on them on days when the waters are calm.'),
(280, NULL, 'Ralts', '280.png', 'Feeling Pokémon', 'Psychic', 'Fairy', 'The horns on its head provide a strong power that enables it to sense people''s emotions.'),
(281, NULL, 'Kirlia', '281.png', 'Emotion Pokémon', 'Psychic', 'Fairy', 'It has a psychic power that enables it to distort the space around it and see into the future.'),
(282, NULL, 'Gardevoir', '282.png', 'Embrace Pokémon', 'Psychic', 'Fairy', 'To protect its Trainer, it will expend all its psychic power to create a small black hole.'),
(283, NULL, 'Surskit', '283.png', 'Pond Skater Pokémon', 'Bug', 'Water', 'It secretes a thick, sweet-scented syrup from the tip of its head. It lives on weed-choked ponds.'),
(284, NULL, 'Masquerain', '284.png', 'Eyeball Pokémon', 'Bug', 'Flying', 'The antennae have distinctive patterns that look like eyes. When it rains, they grow heavy, making flight impossible.'),
(285, NULL, 'Shroomish', '285.png', 'Mushroom Pokémon', 'Grass', NULL, 'If it senses danger, it scatters spores from the top of its head to protect itself.'),
(286, NULL, 'Breloom', '286.png', 'Mushroom Pokémon', 'Grass', 'Fighting', 'It scatters poisonous spores and throws powerful punches while its foe is hampered by inhaled spores.'),
(287, NULL, 'Slakoth', '287.png', 'Slacker Pokémon', 'Normal', NULL, 'It sleeps for 20 hours every day. Making drowsy those that see it is one of its abilities.'),
(288, NULL, 'Vigoroth', '288.png', 'Wild Monkey Pokémon', 'Normal', NULL, 'It is always hungry because it won''t stop rampaging. Even while it is eating, it can''t keep still.'),
(289, NULL, 'Slaking', '289.png', 'Lazy Pokémon', 'Normal', NULL, 'It is the world''s most slothful Pokémon. However, it can exert horrifying power by releasing pent-up energy all at once.'),
(290, NULL, 'Nincada', '290.png', 'Trainee Pokémon', 'Bug', 'Ground', 'It grows underground, sensing its surroundings using antennae instead of its virtually blind eyes.'),
(291, NULL, 'Ninjask', '291.png', 'Ninja Pokémon', 'Bug', 'Flying', 'Because they move so quickly, they sometimes become unseeable. They congregate around tree sap.'),
(292, NULL, 'Shedinja', '292.png', 'Shed Pokémon', 'Bug', 'Ghost', 'It is a discarded bug shell that came to life. Peering into the crack on its back is said to steal one''s spirit.'),
(293, NULL, 'Whismur', '293.png', 'Whisper Pokémon', 'Normal', NULL, 'Usually, its cries are like quiet murmurs. If frightened, it shrieks at the same volume as a jet plane.'),
(294, NULL, 'Loudred', '294.png', 'Big Voice Pokémon', 'Normal', NULL, 'The shock waves from its cries can tip over trucks. It stamps its feet to power up.'),
(295, NULL, 'Exploud', '295.png', 'Loud Noise Pokémon', 'Normal', NULL, 'Its howls can be heard over six miles away. It emits all sorts of noises from the ports on its body.'),
(296, NULL, 'Makuhita', '296.png', 'Guts Pokémon', 'Fighting', NULL, 'It toughens up by slamming into thick trees over and over. It gains a sturdy body and dauntless spirit.'),
(297, NULL, 'Hariyama', '297.png', 'Arm Thrust Pokémon', 'Fighting', NULL, 'It stomps on the ground to build power. It can send a 10-ton truck flying with a straight-arm punch.'),
(298, NULL, 'Azurill', '298.png', 'Polka Dot Pokémon', 'Normal', 'Fairy', 'Its tail bounces like a rubber ball. It flings that tail around to fight opponents bigger than itself.'),
(299, NULL, 'Nosepass', '299.png', 'Compass Pokémon', 'Rock', NULL, 'Its nose is a magnet. As a result, this Pokémon always keeps its face pointing north.'),
(300, NULL, 'Skitty', '300.png', 'Kitten Pokémon', 'Normal', NULL, 'It can''t stop itself from chasing moving things, and it runs in circles, chasing its own tail.'),
(301, NULL, 'Delcatty', '301.png', 'Prim Pokémon', 'Normal', NULL, 'It is highly popular among Trainers for its sublime fur. It does not keep a nest.'),
(302, NULL, 'Sableye', '302.png', 'Darkness Pokémon', 'Dark', 'Ghost', 'Materials from gems it has eaten float to the surface of its body and can form an infinite number of patterns among individuals.'),
(303, NULL, 'Mawile', '303.png', 'Deceiver Pokémon', 'Steel', 'Fairy', 'Attached to its head is a huge set of jaws formed by horns. It can chew through iron beams.'),
(304, NULL, 'Aron', '304.png', 'Iron Armor Pokémon', 'Steel', 'Rock', 'It usually lives deep in mountains. But when it''s hungry, it shows up at the foot of the mountains and eats railroad tracks and cars.'),
(305, NULL, 'Lairon', '305.png', 'Iron Armor Pokémon', 'Steel', 'Rock', 'For food, it digs up iron ore. It smashes its steely body against others to fight over territory.'),
(306, NULL, 'Aggron', '306.png', 'Iron Armor Pokémon', 'Steel', 'Rock', 'While seeking iron for food, it digs tunnels by breaking through bedrock with its steel horns.'),
(307, NULL, 'Meditite', '307.png', 'Meditate Pokémon', 'Fighting', 'Psychic', 'It meditates to heighten its inner energy and to float in the air. It eats one berry a day.'),
(308, NULL, 'Medicham', '308.png', 'Meditate Pokémon', 'Fighting', 'Psychic', 'Through yoga training, it gained the psychic power to predict its foe''s next move.'),
(309, NULL, 'Electrike', '309.png', 'Lightning Pokémon', 'Electric', NULL, 'Using electricity stored in its fur, it stimulates its muscles to heighten its reaction speed.'),
(310, NULL, 'Manectric', '310.png', 'Discharge Pokémon', 'Electric', NULL, 'It discharges electricity from its mane. The Pokémon creates a thundercloud overhead from which to drop lightning bolts.'),
(311, NULL, 'Plusle', '311.png', 'Cheering Pokémon', 'Electric', NULL, 'It cheers on friends with pom-poms made of sparks. It drains power from telephone poles.'),
(312, NULL, 'Minun', '312.png', 'Cheering Pokémon', 'Electric', NULL, 'It cheers on friends. If its friends are losing, its body lets off more and more sparks.'),
(313, NULL, 'Volbeat', '313.png', 'Firefly Pokémon', 'Bug', NULL, 'It communicates with others by lighting up its rear at night. It loves Illumise''s sweet aroma.'),
(314, NULL, 'Illumise', '314.png', 'Firefly Pokémon', 'Bug', NULL, 'With its sweet aroma, it guides Volbeat to draw signs with light in the night sky.'),
(315, NULL, 'Roselia', '315.png', 'Thorn Pokémon', 'Grass', 'Poison', 'The beautiful flowers on its arms have toxic thorns. Don''t even think about picking those flowers.'),
(316, NULL, 'Gulpin', '316.png', 'Stomach Pokémon', 'Poison', NULL, 'It has a small heart and brain. Its stomach comprises most of its body, with enzymes to dissolve anything.'),
(317, NULL, 'Swalot', '317.png', 'Poison Bag Pokémon', 'Poison', NULL, 'It can swallow a tire whole in one gulp. It secretes a horribly toxic fluid from the pores on its body.'),
(318, NULL, 'Carvanha', '318.png', 'Savage Pokémon', 'Water', 'Dark', 'They swarm any foe that invades their territory. Their sharp fangs can tear out boat hulls.'),
(319, NULL, 'Sharpedo', '319.png', 'Brutal Pokémon', 'Water', 'Dark', 'Its fangs rip through sheet iron. It swims at 75 mph and is known as the Bully of the Sea.'),
(320, NULL, 'Wailmer', '320.png', 'Ball Whale Pokémon', 'Water', NULL, 'On sunny days, it lands on beaches to bounce like a ball and play. It spouts water from its nostrils.'),
(321, NULL, 'Wailord', '321.png', 'Float Whale Pokémon', 'Water', NULL, 'It''s the biggest of all Pokémon. It can dive to a depth of almost 10,000 feet on only one breath.'),
(322, NULL, 'Numel', '322.png', 'Numb Pokémon', 'Fire', 'Ground', 'Magma of almost 2,200 degrees Fahrenheit courses through its body. When it grows cold, the magma hardens and slows it.'),
(323, NULL, 'Camerupt', '323.png', 'Eruption Pokémon', 'Fire', 'Ground', 'It lives in the crater of a volcano. It is well known that the humps on its back erupt every 10 years.'),
(324, NULL, 'Torkoal', '324.png', 'Coal Pokémon', 'Fire', NULL, 'Coal is the source of Torkoal''s energy. Large amounts of coal can be found in the mountains where they live.'),
(325, NULL, 'Spoink', '325.png', 'Bounce Pokémon', 'Psychic', NULL, 'Using its tail like a spring, it keeps its heart beating by bouncing constantly. If it stops, it dies.'),
(326, NULL, 'Grumpig', '326.png', 'Manipulate Pokémon', 'Psychic', NULL, 'It can perform odd dance steps to influence foes. Its style of dancing became hugely popular overseas.'),
(327, NULL, 'Spinda', '327.png', 'Spot Panda Pokémon', 'Normal', NULL, 'No two Spinda have the same pattern of spots. Their tottering steps hinder the aim of foes.'),
(328, NULL, 'Trapinch', '328.png', 'Ant Pit Pokémon', 'Ground', NULL, 'It makes a conical pit in desert sand and lies in wait at the bottom for prey to come tumbling down.'),
(329, NULL, 'Vibrava', '329.png', 'Vibration Pokémon', 'Ground', 'Dragon', 'It violently shudders its wings, generating ultrasonic waves to induce headaches in people.'),
(330, NULL, 'Flygon', '330.png', 'Mystic Pokémon', 'Ground', 'Dragon', 'It whips up sandstorms with powerful flaps of its wings. It is known as the Desert Spirit.'),
(331, NULL, 'Cacnea', '331.png', 'Cactus Pokémon', 'Grass', NULL, 'It prefers harsh environments, such as deserts. It can survive for 30 days on water stored in its body.'),
(332, NULL, 'Cacturne', '332.png', 'Scarecrow Pokémon', 'Grass', 'Dark', 'It lives in deserts. It becomes active at night when it hunts for prey exhausted from the desert''s heat.'),
(333, NULL, 'Swablu', '333.png', 'Cotton Bird Pokémon', 'Normal', 'Flying', 'It constantly grooms its cotton-like wings. It takes a shower to clean itself if it becomes dirty.'),
(334, NULL, 'Altaria', '334.png', 'Humming Pokémon', 'Dragon', 'Flying', 'On sunny days, it flies freely through the sky and blends into the clouds. It sings in a beautiful soprano.'),
(335, NULL, 'Zangoose', '335.png', 'Cat Ferret Pokémon', 'Normal', NULL, 'If it comes across a Seviper, its fur bristles and it assumes its battle pose. Its sharp claws are its best weapon.'),
(336, NULL, 'Seviper', '336.png', 'Fang Snake Pokémon', 'Poison', NULL, 'Constant polishing makes the edge of the blade on its tail extremely sharp. It''s Zangoose''s archrival.'),
(337, NULL, 'Lunatone', '337.png', 'Meteorite Pokémon', 'Rock', 'Psychic', 'It becomes active on nights with a full moon, so it is said to have some link to the lunar phases.'),
(338, NULL, 'Solrock', '338.png', 'Meteorite Pokémon', 'Rock', 'Psychic', 'This new Pokémon species is rumored to be an avatar of the sun. The Pokémon gives off light while spinning.'),
(339, NULL, 'Barboach', '339.png', 'Whiskers Pokémon', 'Water', 'Ground', 'It probes muddy riverbeds with its two long whiskers. A slimy film protects its body.'),
(340, NULL, 'Whiscash', '340.png', 'Whiskers Pokémon', 'Water', 'Ground', 'Sighting Whiscash leaping from the water is believed to herald an earthquake.'),
(341, NULL, 'Corphish', '341.png', 'Ruffian Pokémon', 'Water', NULL, 'Its hardy vitality enables it to adapt to any environment. Its pincers will never release prey.'),
(342, NULL, 'Crawdaunt', '342.png', 'Rogue Pokémon', 'Water', 'Dark', 'It is a ruffian that uses its pincers to pick up and toss out other Pokémon from its pond.'),
(343, NULL, 'Baltoy', '343.png', 'Clay Doll Pokémon', 'Ground', 'Psychic', 'It moves by spinning on its foot. It is a rare Pokémon that was discovered in ancient ruins.'),
(344, NULL, 'Claydol', '344.png', 'Clay Doll Pokémon', 'Ground', 'Psychic', 'An ancient clay figurine was exposed to a mysterious ray of light, and it came to life as a Pokémon.'),
(345, NULL, 'Lileep', '345.png', 'Sea Lily Pokémon', 'Rock', 'Grass', 'It lived on the seafloor 100 million years ago and was reanimated scientifically.'),
(346, NULL, 'Cradily', '346.png', 'Barnacle Pokémon', 'Rock', 'Grass', 'It lives in the shallows of warm seas. When the tide goes out, it digs up prey from beaches.'),
(347, NULL, 'Anorith', '347.png', 'Old Shrimp Pokémon', 'Rock', 'Bug', 'This Pokémon ancestor was reanimated from a fossil. It lived in the sea and hunted with its claws.'),
(348, NULL, 'Armaldo', '348.png', 'Plate Pokémon', 'Rock', 'Bug', 'It went ashore after evolving. Its entire body is clad in a sturdy armor.'),
(349, NULL, 'Feebas', '349.png', 'Fish Pokémon', 'Water', NULL, 'They are famous for their shabby appearance. Although populous, they tend to cluster in set locations.'),
(350, NULL, 'Milotic', '350.png', 'Tender Pokémon', 'Water', NULL, 'It is the world''s most beautiful Pokémon. There are many works of art featuring Milotic.'),
(351, NULL, 'Castform', '351.png', 'Weather Pokémon', 'Normal', NULL, 'Its appearance changes with the weather. Recently, its molecules were found to be just like water.'),
(352, NULL, 'Kecleon', '352.png', 'Color Swap Pokémon', 'Normal', NULL, 'It can freely change its body''s color. The zigzag pattern on its belly doesn''t change, however.'),
(353, NULL, 'Shuppet', '353.png', 'Puppet Pokémon', 'Ghost', NULL, 'It feeds on the dark emotions of sadness and hatred, which make it grow steadily stronger.'),
(354, NULL, 'Banette', '354.png', 'Marionette Pokémon', 'Ghost', NULL, 'Strong feelings of hatred turned a puppet into a Pokémon. If it opens its mouth, its cursed energy escapes.'),
(355, NULL, 'Duskull', '355.png', 'Requiem Pokémon', 'Ghost', NULL, 'It doggedly pursues its prey wherever the prey goes. However, the chase is abandoned at sunrise.'),
(356, NULL, 'Dusclops', '356.png', 'Beckon Pokémon', 'Ghost', NULL, 'Its body is hollow. It is said that those who look into its body are sucked into the void.'),
(357, NULL, 'Tropius', '357.png', 'Fruit Pokémon', 'Grass', 'Flying', 'Delicious fruits grew out from around its neck because it always ate the same kind of fruit.'),
(358, NULL, 'Chimecho', '358.png', 'Wind Chime Pokémon', 'Psychic', NULL, 'Can emit waves of air powerful enough to knock out prey taller than itself. I hypothesize that it amplifies the faint sound of wind within its body.'),
(359, NULL, 'Absol', '359.png', 'Disaster Pokémon', 'Dark', NULL, 'It senses coming disasters and appears before people only to warn them of impending danger.'),
(360, NULL, 'Wynaut', '360.png', 'Bright Pokémon', 'Psychic', NULL, 'They grow strong by pushing up against one another en masse. They love eating sweet fruit.'),
(361, NULL, 'Snorunt', '361.png', 'Snow Hat Pokémon', 'Ice', NULL, 'It is said that a home visited by a Snorunt will prosper. It can withstand cold of -150 degrees Fahrenheit.'),
(362, NULL, 'Glalie', '362.png', 'Face Pokémon', 'Ice', NULL, 'Its prey is instantaneously frozen stiff by the cold air it exhales from its huge mouth. While they''re in that frozen state, it gobbles them up.'),
(363, NULL, 'Spheal', '363.png', 'Clap Pokémon', 'Ice', 'Water', 'During the season when drift ice approaches the shore, Spheal prefers living on the ice—where fewer predators lurk—rather than the land. Its fur retains heat superbly and resists harsh cold.'),
(364, NULL, 'Sealeo', '364.png', 'Ball Roll Pokémon', 'Ice', 'Water', 'Its white whiskers are very sensitive. Sealeo will balance Spheal on the tip of its nose, checking its scent and its feel to be sure the Spheal is healthy.'),
(365, NULL, 'Walrein', '365.png', 'Ice Break Pokémon', 'Ice', 'Water', 'It shatters ice with its big tusks. Its thick blubber repels not only the cold but also enemy attacks.'),
(366, NULL, 'Clamperl', '366.png', 'Bivalve Pokémon', 'Water', NULL, 'It makes a single pearl during its lifetime. The pearl is said to amplify psychic power.'),
(367, NULL, 'Huntail', '367.png', 'Deep Sea Pokémon', 'Water', NULL, 'It lives deep in the sea. With a tail shaped like a small fish, it attracts unsuspecting prey.'),
(368, NULL, 'Gorebyss', '368.png', 'South Sea Pokémon', 'Water', NULL, 'It lives at the bottom of the sea. In the springtime, its pink body turns more vivid for some reason.'),
(369, NULL, 'Relicanth', '369.png', 'Longevity Pokémon', 'Water', 'Rock', 'This rare Pokémon was discovered during a deep-sea exploration. It has not changed in over 100 million years.'),
(370, NULL, 'Luvdisc', '370.png', 'Rendezvous Pokémon', 'Water', NULL, 'During the spawning season, countless Luvdisc congregate at coral reefs, turning the waters pink.'),
(371, NULL, 'Bagon', '371.png', 'Rock Head Pokémon', 'Dragon', NULL, 'Its belief that it will be able to fly one day is apparently the influence of information carried in its genes.'),
(372, NULL, 'Shelgon', '372.png', 'Endurance Pokémon', 'Dragon', NULL, 'Its armored body makes all attacks bounce off. The armor is too tough, however, making it heavy and somewhat sluggish.'),
(373, NULL, 'Salamence', '373.png', 'Dragon Pokémon', 'Dragon', 'Flying', 'It flies around on its wings, which have grown in at last. In its happiness, it gushes hot flames, burning up everything it passes over.'),
(374, NULL, 'Beldum', '374.png', 'Iron Ball Pokémon', 'Steel', 'Psychic', 'They converse with one another by using magnetic pulses. In a swarm, they move in perfect unison.'),
(375, NULL, 'Metang', '375.png', 'Iron Claw Pokémon', 'Steel', 'Psychic', 'It is formed by two Beldum joining together. Its steel body won''t be scratched if it collides with a jet.'),
(376, NULL, 'Metagross', '376.png', 'Iron Leg Pokémon', 'Steel', 'Psychic', 'Metang combined to form it. With four brains, it has the intelligence of a supercomputer.'),
(377, NULL, 'Regirock', '377.png', 'Rock Peak Pokémon', 'Rock', NULL, 'Its entire body is made of rock. If any part chips off in battle, Regirock attaches rocks to repair itself.'),
(378, NULL, 'Regice', '378.png', 'Iceberg Pokémon', 'Ice', NULL, 'Its body is made of ice from the ice age. It controls frigid air of -328 degrees Fahrenheit.'),
(379, NULL, 'Registeel', '379.png', 'Iron Pokémon', 'Steel', NULL, 'Tempered by pressure underground over tens of thousands of years, its body cannot be scratched.'),
(380, NULL, 'Latias', '380.png', 'Eon Pokémon', 'Dragon', 'Psychic', 'Its body is covered with a down that can refract light in such a way that it becomes invisible.'),
(381, NULL, 'Latios', '381.png', 'Eon Pokémon', 'Dragon', 'Psychic', 'It is a highly intelligent Pokémon. By folding back its forelegs in flight, it can overtake jet planes.'),
(382, NULL, 'Kyogre', '382.png', 'Sea Basin Pokémon', 'Water', NULL, 'It is said to have widened the seas by causing downpours. It had been asleep in a marine trench.'),
(383, NULL, 'Groudon', '383.png', 'Continent Pokémon', 'Ground', NULL, 'It had been asleep in underground magma ever since it fiercely fought Kyogre long ago.'),
(384, NULL, 'Rayquaza', '384.png', 'Sky High Pokémon', 'Dragon', 'Flying', 'It lives in the ozone layer far above the clouds and cannot be seen from the ground.'),
(385, NULL, 'Jirachi', '385.png', 'Wish Pokémon', 'Steel', 'Psychic', 'It is said to wake up for just seven days every 1,000 years and use its power to grant any wish.'),
(386, NULL, 'Deoxys', '386.png', 'DNA Pokémon', 'Psychic', NULL, 'An alien virus that fell to earth on a meteorite underwent a DNA mutation to become this Pokémon.'),
(387, NULL, 'Turtwig', '387.png', 'Tiny Leaf Pokémon', 'Grass', NULL, 'This Pokémon becomes more energetic the more sunlight there is. The part resembling a shell is similar to silt and is slightly damp and warm to the touch.'),
(388, NULL, 'Grotle', '388.png', 'Grove Pokémon', 'Grass', NULL, 'Appears where there is clean spring water. The fruit that grows on the shrubs on its shell is sweet, nutritious, and truly delicious.'),
(389, NULL, 'Torterra', '389.png', 'Continent Pokémon', 'Grass', 'Ground', 'This remarkable, large-bodied Pokémon would serve beautifully as borrowed scenery for a garden, and its strength is peerless. Torterra roams the wilderness in search of clean water.'),
(390, NULL, 'Chimchar', '390.png', 'Chimp Pokémon', 'Fire', NULL, 'It agilely scales sheer cliffs to live atop craggy mountains. Its fire is put out when it sleeps.'),
(391, NULL, 'Monferno', '391.png', 'Playful Pokémon', 'Fire', 'Fighting', 'The deeper the blue on its face, the more powerful it will grow to become. It leaps about every which way and lands powerful blows against its opponents with the flame on its tail.'),
(392, NULL, 'Infernape', '392.png', 'Flame Pokémon', 'Fire', 'Fighting', 'A tall, hardy Pokémon with a dazzling appearance. It shrouds itself in flame and battles as if engaged in dance—truly a sight to behold.'),
(393, NULL, 'Piplup', '393.png', 'Penguin Pokémon', 'Water', NULL, 'Prefers cold climes and appears along coasts. It''s an adorable little thing—as cute as any child—but it''s also prideful, unwilling to accept handouts from people.'),
(394, NULL, 'Prinplup', '394.png', 'Penguin Pokémon', 'Water', NULL, 'It swims gracefully through the frigid sea and sings with a voice like the roaring tide. It has powerful, sturdy wings and dignity to match.'),
(395, NULL, 'Empoleon', '395.png', 'Emperor Pokémon', 'Water', 'Steel', 'It swims as fast as a jet boat. The edges of its wings are sharp and can slice apart drifting ice.'),
(396, NULL, 'Starly', '396.png', 'Starling Pokémon', 'Normal', 'Flying', 'Because they are weak individually, they form groups. However, they bicker if the group grows too big.'),
(397, NULL, 'Staravia', '397.png', 'Starling Pokémon', 'Normal', 'Flying', 'Recognizing their own weakness, they always live in a group. When alone, a Staravia cries noisily.'),
(398, NULL, 'Staraptor', '398.png', 'Predator Pokémon', 'Normal', 'Flying', 'When Staravia evolve into Staraptor, they leave the flock to live alone. They have sturdy wings.'),
(399, NULL, 'Bidoof', '399.png', 'Plump Mouse Pokémon', 'Normal', NULL, 'Bidoof has an unsophisticated face and is rarely flustered by anything. There have been incidents involving Bidoof sauntering into villages and gnawing on the houses without a single care.'),
(400, NULL, 'Bibarel', '400.png', 'Beaver Pokémon', 'Normal', 'Water', 'Bibarel fur repels water and is also a fantastic material for heat retention. These Pokémon create dams on rivers to live in.'),
(401, NULL, 'Kricketot', '401.png', 'Cricket Pokémon', 'Bug', NULL, 'Its legs are short. Whenever it stumbles, its stiff antennae clack with a xylophone-like sound.'),
(402, NULL, 'Kricketune', '402.png', 'Cricket Pokémon', 'Bug', NULL, 'By allowing its cry to resonate in the hollow of its belly, it produces a captivating sound.'),
(403, NULL, 'Shinx', '403.png', 'Flash Pokémon', 'Electric', NULL, 'The extension and contraction of its muscles generates electricity. It glows when in trouble.'),
(404, NULL, 'Luxio', '404.png', 'Spark Pokémon', 'Electric', NULL, 'Strong electricity courses through the tips of its sharp claws. A light scratch causes fainting in foes.'),
(405, NULL, 'Luxray', '405.png', 'Gleam Eyes Pokémon', 'Electric', NULL, 'It can see clearly through walls to track down its prey and seek its lost young.'),
(406, NULL, 'Budew', '406.png', 'Bud Pokémon', 'Grass', 'Poison', 'When the sun''s light strengthens, the bud atop this Pokémon''s head opens. This is a sign to the people that the harsh winter is over, and the season of budding has begun.'),
(407, NULL, 'Roserade', '407.png', 'Bouquet Pokémon', 'Grass', 'Poison', 'Hidden within the bouquet on each hand are thorned whips loaded with virulent poison. Roserade moves gracefully as it corners its prey and mercilessly lashes them with its whips.'),
(408, NULL, 'Cranidos', '408.png', 'Head Butt Pokémon', 'Rock', NULL, 'An incredibly rare sight. They duel each other by ramming their heads together, and the resulting sound echoes throughout the area like the pealing of a bell.'),
(409, NULL, 'Rampardos', '409.png', 'Head Butt Pokémon', 'Rock', NULL, 'Very little is known about its biology. Can knock down massive trees by smashing its beautiful, pearl-like crown against them.'),
(410, NULL, 'Shieldon', '410.png', 'Shield Pokémon', 'Rock', 'Steel', 'Much remains unknown about this Pokémon, as few have ever seen it. However, we know that it is calm and dislikes conflict, and it enjoys polishing its face against trees and rocks.'),
(411, NULL, 'Bastiodon', '411.png', 'Shield Pokémon', 'Rock', 'Steel', 'Its face is sturdy—as strong as diamond—and this hardness offers a very stable defense. Much about this species is still unknown, such as its natural habitat.'),
(412, NULL, 'Burmy', '412.png', 'Bagworm Pokémon', 'Bug', NULL, 'If its cloak is even slightly damaged, Burmy will immediately repair it with whatever is close at hand. The Pokémon within the cloak is scrawny and vulnerable to the cold.'),
(413, NULL, 'Wormadam', '413.png', 'Bagworm Pokémon', 'Bug', 'Grass', 'The cloak—fashioned from plant matter—has merged with the Pokémon and is now part of the body, like fur or skin. I suspect this fusion is an effect of the energy involved in evolution.'),
(414, NULL, 'Mothim', '414.png', 'Moth Pokémon', 'Bug', 'Flying', 'Scatters steel-colored scales as it flaps its wings. Despite being observed feeding primarily on the nectar of flowers, Mothim is not often seen around flower gardens.'),
(415, NULL, 'Combee', '415.png', 'Tiny Bee Pokémon', 'Bug', 'Flying', 'The trio is together from birth. It constantly gathers nectar from flowers to please Vespiquen.'),
(416, NULL, 'Vespiquen', '416.png', 'Beehive Pokémon', 'Bug', 'Flying', 'It houses its colony in cells in its body and releases various pheromones to make those grubs do its bidding.'),
(417, NULL, 'Pachirisu', '417.png', 'EleSquirrel Pokémon', 'Electric', NULL, 'A pair may be seen rubbing their cheek pouches together in an effort to share stored electricity.'),
(418, NULL, 'Buizel', '418.png', 'Sea Weasel Pokémon', 'Water', NULL, 'It spins its two tails like a screw to propel itself through water. The tails also slice clinging seaweed.'),
(419, NULL, 'Floatzel', '419.png', 'Sea Weasel Pokémon', 'Water', NULL, 'With its flotation sac inflated, it can carry people on its back. It deflates the sac before it dives.'),
(420, NULL, 'Cherubi', '420.png', 'Cherry Pokémon', 'Grass', NULL, 'Once the fruit growing alongside the main body is large and plump, Cherubi will use the nutrients within to evolve. The fruit then detaches, becoming nourishment for other creatures.'),
(421, NULL, 'Cherrim', '421.png', 'Blossom Pokémon', 'Grass', NULL, 'It is docile as a bud and turns cheerful when it blooms. It folds back into a bud if sunlight wanes.'),
(422, NULL, 'Shellos', '422.png', 'Sea Slug Pokémon', 'Water', NULL, 'Found in abundance on seashores bordering warm waters. Shellos are unexpectedly friendly and will crawl toward any person they see. Take care not to get coated in mucus!'),
(423, NULL, 'Gastrodon', '423.png', 'Sea Slug Pokémon', 'Water', 'Ground', 'Eats beach sand for nourishment. Should one Gastrodon encounter another of a different color, a fierce battle will inevitably ensue.'),
(424, NULL, 'Ambipom', '424.png', 'Long Tail Pokémon', 'Normal', NULL, 'To affirm their kinship, members of this species will form a ring by linking their newly doubled tails together. On rare occasions, humans have been accepted into such rings.'),
(425, NULL, 'Drifloon', '425.png', 'Balloon Pokémon', 'Ghost', 'Flying', 'Said to lure away young children and carry them off to the afterlife. Some whisper that Drifloon are formed of reincarnated human souls, but these rumors are as yet unconfirmed.'),
(426, NULL, 'Drifblim', '426.png', 'Blimp Pokémon', 'Ghost', 'Flying', 'It can generate and release gas within its body. That''s how it can control the altitude of its drift.'),
(427, NULL, 'Buneary', '427.png', 'Rabbit Pokémon', 'Normal', NULL, 'When it senses danger, it perks up its ears. On cold nights, it sleeps with its head tucked into its fur.'),
(428, NULL, 'Lopunny', '428.png', 'Rabbit Pokémon', 'Normal', NULL, 'Its fur is warm and yet remarkably light. This Pokémon kicks as though it were a master of karate, driving back its opponents with ease.'),
(429, NULL, 'Mismagius', '429.png', 'Magical Pokémon', 'Ghost', NULL, 'Its cry sounds like an incantation. It is said the cry may rarely be imbued with happiness-giving power.'),
(430, NULL, 'Honchkrow', '430.png', 'Big Boss Pokémon', 'Dark', 'Flying', 'It is merciless by nature. It is said that it never forgives the mistakes of its Murkrow followers.'),
(431, NULL, 'Glameow', '431.png', 'Catty Pokémon', 'Normal', NULL, 'Bewitches humans with its helical tail and piercing gaze. Its hidden claws are quite sharp as well, making this Pokémon an exceedingly tricky opponent if antagonized.'),
(432, NULL, 'Purugly', '432.png', 'Tiger Cat Pokémon', 'Normal', NULL, 'To make itself appear intimidatingly beefy, it tightly cinches its waist with its twin tails.'),
(433, NULL, 'Chingling', '433.png', 'Bell Pokémon', 'Psychic', NULL, 'This Pokémon gave me an excruciating headache when it seemingly cried out without making a sound. Perhaps there are some sounds that the human ear is simply incapable of hearing.'),
(434, NULL, 'Stunky', '434.png', 'Skunk Pokémon', 'Poison', 'Dark', 'It sprays a foul fluid from its rear. Its stench spreads over a mile radius, driving Pokémon away.'),
(435, NULL, 'Skuntank', '435.png', 'Skunk Pokémon', 'Poison', 'Dark', 'It attacks by spraying a repugnant fluid from its tail, but the stench dulls after a few squirts.'),
(436, NULL, 'Bronzor', '436.png', 'Bronze Pokémon', 'Steel', 'Psychic', 'They are found in ancient tombs. The patterns on their backs are said to be imbued with mysterious power.'),
(437, NULL, 'Bronzong', '437.png', 'Bronze Bell Pokémon', 'Steel', 'Psychic', 'It brought rains by opening portals to another world. It was revered as a bringer of plentiful harvests.'),
(438, NULL, 'Bonsly', '438.png', 'Bonsai Pokémon', 'Rock', NULL, 'From its eyes, it can expel excess moisture from its body. This liquid is similar in composition to human sweat.'),
(439, NULL, 'Mime Jr.', '439.png', 'Mime Pokémon', 'Psychic', 'Fairy', 'It likes places where people gather. It mimics foes to confuse them, then makes its getaway.'),
(440, NULL, 'Happiny', '440.png', 'Playhouse Pokémon', 'Normal', NULL, 'It carefully carries a round, white rock that it thinks is an egg. It''s bothered by how curly its hair looks.'),
(441, NULL, 'Chatot', '441.png', 'Music Note Pokémon', 'Normal', 'Flying', 'A versatile performer skilled in the imitation of human speech. It is said that older, more experienced Chatot can even understand the meaning of the words they mimic.'),
(442, NULL, 'Spiritomb', '442.png', 'Forbidden Pokémon', 'Ghost', 'Dark', 'It was formed by uniting 108 spirits. It has been bound to the Odd Keystone to keep it from doing any mischief.'),
(443, NULL, 'Gible', '443.png', 'Land Shark Pokémon', 'Dragon', 'Ground', 'It skulks in caves, and when prey or an enemy passes by, it leaps out and chomps them. The force of its attack sometimes chips its teeth.'),
(444, NULL, 'Gabite', '444.png', 'Cave Pokémon', 'Dragon', 'Ground', 'In rare cases, it molts and sheds its scales. Medicine containing its scales as an ingredient will make a weary body feel invigorated.'),
(445, NULL, 'Garchomp', '445.png', 'Mach Pokémon', 'Dragon', 'Ground', 'It is said that when one runs at high speed, its wings create blades of wind that can fell nearby trees.'),
(446, NULL, 'Munchlax', '446.png', 'Big Eater Pokémon', 'Normal', NULL, 'It wolfs down its weight in food once a day, swallowing it whole with almost no chewing.'),
(447, NULL, 'Riolu', '447.png', 'Emanation Pokémon', 'Fighting', NULL, 'They communicate with one another using their auras. They are able to run all through the night.'),
(448, NULL, 'Lucario', '448.png', 'Aura Pokémon', 'Fighting', 'Steel', 'It''s said that no foe can remain invisible to Lucario, since it can detect auras—even those of foes it could not otherwise see.'),
(449, NULL, 'Hippopotas', '449.png', 'Hippo Pokémon', 'Ground', NULL, 'It shuts its nostrils tight, then travels through sand as if walking. They form colonies of around 10.'),
(450, NULL, 'Hippowdon', '450.png', 'Heavyweight Pokémon', 'Ground', NULL, 'It is surprisingly quick to anger. It holds its mouth agape as a display of its strength.'),
(451, NULL, 'Skorupi', '451.png', 'Scorpion Pokémon', 'Poison', 'Bug', 'Its claws are not only razor-sharp but poisonous, making Skorupi a highly dangerous Pokémon. It seems to be weakened by cold temperatures, however.'),
(452, NULL, 'Drapion', '452.png', 'Ogre Scorp Pokémon', 'Poison', 'Dark', 'Has a brutish, ferocious temperament. With immense strength and a sturdy shell off which swords will bounce, it rampages about and wreaks havoc.'),
(453, NULL, 'Croagunk', '453.png', 'Toxic Mouth Pokémon', 'Poison', 'Fighting', 'Inflating its poison sacs, it fills the area with an odd sound and hits flinching opponents with a poison jab.'),
(454, NULL, 'Toxicroak', '454.png', 'Toxic Mouth Pokémon', 'Poison', 'Fighting', 'Swaying and dodging the attacks of its foes, it weaves its flexible body in close, then lunges out with its poisonous claws.'),
(455, NULL, 'Carnivine', '455.png', 'Bug Catcher Pokémon', 'Grass', NULL, 'Though this is a plant Pokémon, it has a gluttonous and unruly temperament. Carnivine attacks its prey with its cavernous maw wide open.'),
(456, NULL, 'Finneon', '456.png', 'Wing Fish Pokémon', 'Water', NULL, 'The line running down its side can store sunlight. It shines vividly at night.'),
(457, NULL, 'Lumineon', '457.png', 'Neon Pokémon', 'Water', NULL, 'With its shining light, it lures its prey close. However, the light also happens to attract ferocious fish Pokémon—its natural predators.'),
(458, NULL, 'Mantyke', '458.png', 'Kite Pokémon', 'Water', 'Flying', 'Though ball-like in shape, this Pokémon is a proficient swimmer. I have discovered that if a Mantyke spends much time with schools of Remoraid, it will eventually achieve evolution.'),
(459, NULL, 'Snover', '459.png', 'Frost Tree Pokémon', 'Grass', 'Ice', 'During cold seasons, it migrates to the mountain''s lower reaches. It returns to the snow-covered summit in the spring.'),
(460, NULL, 'Abomasnow', '460.png', 'Frost Tree Pokémon', 'Grass', 'Ice', 'It lives a quiet life on mountains that are perpetually covered in snow. It hides itself by whipping up blizzards.'),
(461, NULL, 'Weavile', '461.png', 'Sharp Claw Pokémon', 'Dark', 'Ice', 'They travel in groups of four or five, leaving signs for one another on trees and rocks. They bring down their prey with coordinated attacks.'),
(462, NULL, 'Magnezone', '462.png', 'Magnet Area Pokémon', 'Electric', 'Steel', 'Exposure to a special magnetic field changed Magneton''s molecular structure, turning it into Magnezone.'),
(463, NULL, 'Lickilicky', '463.png', 'Licking Pokémon', 'Normal', NULL, 'Its tongue can extend and contract freely, and it is capable of reaching lengths over 10 times Lickilicky''s height. Beware of the saliva, as it contains corrosive elements.'),
(464, NULL, 'Rhyperior', '464.png', 'Drill Pokémon', 'Ground', 'Rock', 'It puts rocks in holes in its palms and uses its muscles to shoot them. On rare occasions, the Pokémon even shoots out Geodude.'),
(465, NULL, 'Tangrowth', '465.png', 'Vine Pokémon', 'Grass', NULL, 'Draped with long vines, it resembles a shrub in appearance. It swings bundles of vines as though they were arms, wrapping them around prey to ensnare them.'),
(466, NULL, 'Electivire', '466.png', 'Thunderbolt Pokémon', 'Electric', NULL, 'Its evolution was induced by an unusual item, and its electrical output rises along with its heart rate. From its tails, it can unleash an electric current measuring 20,000 volts.'),
(467, NULL, 'Magmortar', '467.png', 'Blast Pokémon', 'Fire', NULL, 'Use of a strange item caused this Pokémon to evolve. Fireballs launched from the ends of its tubelike arms are hot enough to melt an iron pot in an instant.'),
(468, NULL, 'Togekiss', '468.png', 'Jubilee Pokémon', 'Fairy', 'Flying', 'It will never appear where there is strife. Sightings of this Pokémon have recently become rare.'),
(469, NULL, 'Yanmega', '469.png', 'Ogre Darner Pokémon', 'Bug', 'Flying', 'It prefers to battle by biting apart foes'' heads instantly while flying by at high speed.'),
(470, NULL, 'Leafeon', '470.png', 'Verdant Pokémon', 'Grass', NULL, 'The younger they are, the more they smell like fresh grass. With age, their fragrance takes on the odor of fallen leaves.'),
(471, NULL, 'Glaceon', '471.png', 'Fresh Snow Pokémon', 'Ice', NULL, 'It can control its body temperature at will. This enables it to freeze the moisture in the atmosphere, creating flurries of diamond dust.'),
(472, NULL, 'Gliscor', '472.png', 'Fang Scorp Pokémon', 'Ground', 'Flying', 'It glides soundlessly on pitch-black wings and sinks sharp fangs into the throat of its prey. It takes on a look of satisfaction once it has entirely drained its prey of blood.'),
(473, NULL, 'Mamoswine', '473.png', 'Twin Tusk Pokémon', 'Ice', 'Ground', 'Its impressive tusks are made of ice. The ice age is over and the climate has warmed, so this Pokémon''s population has thinned.'),
(474, NULL, 'Porygon-Z', '474.png', 'Virtual Pokémon', 'Normal', NULL, 'Additional software was installed to make it an even better Pokémon. It began acting oddly, however.'),
(475, NULL, 'Gallade', '475.png', 'Blade Pokémon', 'Psychic', 'Fighting', 'When trying to protect someone, it extends its elbows as if they were swords and fights savagely.'),
(476, NULL, 'Probopass', '476.png', 'Compass Pokémon', 'Rock', 'Steel', 'It is able to emit powerful magnetism, allowing it control over the iron sand that forms its luscious mustache. Using this iron sand, Probopass forms hard stones with which it smites its prey.'),
(477, NULL, 'Dusknoir', '477.png', 'Gripper Pokémon', 'Ghost', NULL, 'Comes to those whose lives have come to an end and escorts their souls to the afterlife. Known to mistakenly take the souls of those who yet have life left in them, albeit rarely.'),
(478, NULL, 'Froslass', '478.png', 'Snow Land Pokémon', 'Ice', 'Ghost', 'It spits out cold air of nearly -60 degrees Fahrenheit to freeze its quarry. It brings frozen prey back to its lair and neatly lines them up.'),
(479, NULL, 'Rotom', '479.png', 'Plasma Pokémon', 'Electric', 'Ghost', 'Its electricity-like body can enter some kinds of machines and take control in order to make mischief.'),
(480, NULL, 'Uxie', '480.png', 'Knowledge Pokémon', 'Psychic', NULL, 'A Pokémon feared but also respected for stealing away the memories of evildoers. I have found records that suggest Uxie holds dominion over knowledge.'),
(481, NULL, 'Mesprit', '481.png', 'Emotion Pokémon', 'Psychic', NULL, 'Known as the Being of Emotion. In legend, this Pokémon was feared, as any who showed disrespect would have their emotions thrown into disarray.'),
(482, NULL, 'Azelf', '482.png', 'Willpower Pokémon', 'Psychic', NULL, 'The dreaded Being of Willpower. Legends tell of this Pokémon manipulating the will of its adversaries and turning them into puppets of its own.'),
(483, NULL, 'Dialga', '483.png', 'Temporal Pokémon', 'Steel', 'Dragon', 'This Pokémon is spoken of in legend. It is said that time began moving when Dialga was born.'),
(484, NULL, 'Palkia', '484.png', 'Spatial Pokémon', 'Water', 'Dragon', 'It is said to live in a gap in the spatial dimension parallel to ours. Palkia appears in mythology.'),
(485, NULL, 'Heatran', '485.png', 'Lava Dome Pokémon', 'Fire', 'Steel', 'It dwells in volcanic caves. It digs in with its cross-shaped feet to crawl on ceilings and walls.'),
(486, NULL, 'Regigigas', '486.png', 'Colossal Pokémon', 'Normal', NULL, 'It''s said that Regigigas created other Pokémon from many different materials before it moved the continents to where they are today.'),
(487, NULL, 'Giratina', '487.png', 'Renegade Pokémon', 'Ghost', 'Dragon', 'A Pokémon that is said to live in a world on the reverse side of ours. It appears in an ancient cemetery.'),
(488, NULL, 'Cresselia', '488.png', 'Lunar Pokémon', 'Psychic', NULL, 'When it flies, it releases shiny particles from its veil-like wings. It is said to represent the crescent moon.'),
(489, NULL, 'Phione', '489.png', 'Sea Drifter Pokémon', 'Water', NULL, 'A Pokémon that lives in warm seas. It inflates the flotation sac on its head to drift and search for food.'),
(490, NULL, 'Manaphy', '490.png', 'Seafaring Pokémon', 'Water', NULL, 'Water makes up 80 percent of its body. This Pokémon is easily affected by its environment.'),
(491, NULL, 'Darkrai', '491.png', 'Pitch-Black Pokémon', 'Dark', NULL, 'Folklore has it that on moonless nights, this Pokémon will make people see horrific nightmares.'),
(492, NULL, 'Shaymin', '492.png', 'Gratitude Pokémon', 'Grass', NULL, 'It can dissolve toxins in the air to instantly transform ruined land into a lush field of flowers.'),
(493, NULL, 'Arceus', '493.png', 'Alpha Pokémon', 'Normal', NULL, 'It is told in mythology that this Pokémon was the first Pokémon born before the universe even existed.'),
(494, NULL, 'Victini', '494.png', 'Victory Pokémon', 'Psychic', 'Fire', 'This Pokémon brings victory. It is said that Trainers with Victini always win, regardless of the type of encounter.'),
(495, NULL, 'Snivy', '495.png', 'Grass Snake Pokémon', 'Grass', NULL, 'They photosynthesize by bathing their tails in sunlight. When they are not feeling well, their tails droop.'),
(496, NULL, 'Servine', '496.png', 'Grass Snake Pokémon', 'Grass', NULL, 'It moves along the ground as if sliding. Its swift movements befuddle its foes, and it then attacks with a vine whip.'),
(497, NULL, 'Serperior', '497.png', 'Regal Pokémon', 'Grass', NULL, 'It can stop its opponents'' movements with just a glare. It takes in solar energy and boosts it internally.'),
(498, NULL, 'Tepig', '498.png', 'Fire Pig Pokémon', 'Fire', NULL, 'It loves to eat roasted berries, but sometimes it gets too excited and burns them to a crisp.'),
(499, NULL, 'Pignite', '499.png', 'Fire Pig Pokémon', 'Fire', 'Fighting', 'When its internal fire flares up, its movements grow sharper and faster. When in trouble, it emits smoke.'),
(500, NULL, 'Emboar', '500.png', 'Mega Fire Pig Pokémon', 'Fire', 'Fighting', 'It has mastered fast and powerful fighting moves. It grows a beard of fire.'),
(501, NULL, 'Oshawott', '501.png', 'Sea Otter Pokémon', 'Water', NULL, 'It fights using the scalchop on its stomach. In response to an attack, it retaliates immediately by slashing.'),
(502, NULL, 'Dewott', '502.png', 'Discipline Pokémon', 'Water', NULL, 'As a result of strict training, each Dewott learns different forms for using the scalchops.'),
(503, NULL, 'Samurott', '503.png', 'Formidable Pokémon', 'Water', NULL, 'One swing of the sword incorporated in its armor can fell an opponent. A simple glare from one of them quiets everybody.'),
(504, NULL, 'Patrat', '504.png', 'Scout Pokémon', 'Normal', NULL, 'Extremely cautious, one of them will always be on the lookout, but it won''t notice a foe coming from behind.'),
(505, NULL, 'Watchog', '505.png', 'Lookout Pokémon', 'Normal', NULL, 'When they see an enemy, their tails stand high, and they spit the seeds of berries stored in their cheek pouches.'),
(506, NULL, 'Lillipup', '506.png', 'Puppy Pokémon', 'Normal', NULL, 'This Pokémon is far brighter than the average child, and Lillipup won''t forget the love it receives or any abuse it suffers.'),
(507, NULL, 'Herdier', '507.png', 'Loyal Dog Pokémon', 'Normal', NULL, 'The black fur that covers this Pokémon''s body is dense and springy. Even sharp fangs bounce right off.'),
(508, NULL, 'Stoutland', '508.png', 'Big-Hearted Pokémon', 'Normal', NULL, 'Stoutland is immensely proud of its impressive moustache. It''s said that moustache length is what determines social standing among this species.'),
(509, NULL, 'Purrloin', '509.png', 'Devious Pokémon', 'Dark', NULL, 'Opponents that get drawn in by its adorable behavior come away with stinging scratches from its claws and stinging pride from its laughter.'),
(510, NULL, 'Liepard', '510.png', 'Cruel Pokémon', 'Dark', NULL, 'Don''t be fooled by its gorgeous fur and elegant figure. This is a moody and vicious Pokémon.'),
(511, NULL, 'Pansage', '511.png', 'Grass Monkey Pokémon', 'Grass', NULL, 'It''s good at finding berries and gathers them from all over. It''s kind enough to share them with friends.'),
(512, NULL, 'Simisage', '512.png', 'Thorn Monkey Pokémon', 'Grass', NULL, 'Ill tempered, it fights by swinging its barbed tail around wildly. The leaf growing on its head is very bitter.'),
(513, NULL, 'Pansear', '513.png', 'High Temp Pokémon', 'Fire', NULL, 'This Pokémon lives in caves in volcanoes. The fire within the tuft on its head can reach 600 degrees Fahrenheit.'),
(514, NULL, 'Simisear', '514.png', 'Ember Pokémon', 'Fire', NULL, 'When it gets excited, embers rise from its head and tail and it gets hot. For some reason, it loves sweets.'),
(515, NULL, 'Panpour', '515.png', 'Spray Pokémon', 'Water', NULL, 'The water stored inside the tuft on its head is full of nutrients. Plants that receive its water grow large'),
(516, NULL, 'Simipour', '516.png', 'Geyser Pokémon', 'Water', NULL, 'It prefers places with clean water. When its tuft runs low, it replenishes it by siphoning up water with its tail.'),
(517, NULL, 'Munna', '517.png', 'Dream Eater Pokémon', 'Psychic', NULL, 'It eats dreams and releases mist. The mist is pink when it''s eating a good dream, and black when it''s eating a nightmare.'),
(518, NULL, 'Musharna', '518.png', 'Drowsing Pokémon', 'Psychic', NULL, 'It drowses and dreams all the time. It''s best to leave it be if it''s just woken up, as it''s a terrible grump when freshly roused from sleep.'),
(519, NULL, 'Pidove', '519.png', 'Tiny Pigeon Pokémon', 'Normal', 'Flying', 'Where people go, these Pokémon follow. If you''re scattering food for them, be careful— several hundred of them can gather at once.'),
(520, NULL, 'Tranquill', '520.png', 'Wild Pigeon Pokémon', 'Normal', 'Flying', 'These bright Pokémon have acute memories. Apparently delivery workers often choose them as their partners.'),
(521, NULL, 'Unfezant', '521.png', 'Proud Pokémon', 'Normal', 'Flying', 'Males swing their head plumage to threaten opponents. The females'' flying abilities surpass those of the males.'),
(522, NULL, 'Blitzle', '522.png', 'Electrified Pokémon', 'Electric', NULL, 'Its mane shines when it discharges electricity. They use the frequency and rhythm of these flashes to communicate.'),
(523, NULL, 'Zebstrika', '523.png', 'Thunderbolt Pokémon', 'Electric', NULL, 'They have lightning-like movements. When Zebstrika run at full speed, the sound of thunder reverberates.'),
(524, NULL, 'Roggenrola', '524.png', 'Mantle Pokémon', 'Rock', NULL, 'When it detects a noise, it starts to move. The energy core inside it makes this Pokémon slightly warm to the touch.'),
(525, NULL, 'Boldore', '525.png', 'Ore Pokémon', 'Rock', NULL, 'It relies on sound in order to monitor what''s in its vicinity. When angered, it will attack without ever changing the direction it''s facing.'),
(526, NULL, 'Gigalith', '526.png', 'Compressed Pokémon', 'Rock', NULL, 'Although its energy blasts can blow away a dump truck, they have a limitation— they can only be fired when the sun is out.'),
(527, NULL, 'Woobat', '527.png', 'Bat Pokémon', 'Psychic', 'Flying', 'While inside a cave, if you look up and see lots of heart-shaped marks lining the walls, it''s evidence that Woobat live there.'),
(528, NULL, 'Swoobat', '528.png', 'Courting Pokémon', 'Psychic', 'Flying', 'The auspicious shape of this Pokémon''s nose apparently led some regions to consider Swoobat a symbol of good luck.'),
(529, NULL, 'Drilbur', '529.png', 'Mole Pokémon', 'Ground', NULL, 'It''s a digger, using its claws to burrow through the ground. It causes damage to vegetable crops, so many farmers have little love for it.'),
(530, NULL, 'Excadrill', '530.png', 'Subterrene Pokémon', 'Ground', 'Steel', 'Known as the Drill King, this Pokémon can tunnel through the terrain at speeds of over 90 mph.'),
(531, NULL, 'Audino', '531.png', 'Hearing Pokémon', 'Normal', NULL, 'This Pokémon has a kind heart. By touching with its feelers, Audino can gauge other creatures'' feelings and physical conditions.'),
(532, NULL, 'Timburr', '532.png', 'Muscular Pokémon', 'Fighting', NULL, 'Timburr that have started carrying logs that are about three times their size are nearly ready to evolve.'),
(533, NULL, 'Gurdurr', '533.png', 'Muscular Pokémon', 'Fighting', NULL, 'Gurdurr excels at demolition—construction is not its forte. In any case, there''s skill in the way this Pokémon wields its metal beam.'),
(534, NULL, 'Conkeldurr', '534.png', 'Muscular Pokémon', 'Fighting', NULL, 'When going all out, this Pokémon throws aside its concrete pillars and leaps at opponents to pummel them with its fists.'),
(535, NULL, 'Tympole', '535.png', 'Tadpole Pokémon', 'Water', NULL, 'It uses sound waves to communicate with others of its kind. People and other Pokémon species can''t hear its cries of warning.'),
(536, NULL, 'Palpitoad', '536.png', 'Vibration Pokémon', 'Water', 'Ground', 'On occasion, their cries are sublimely pleasing to the ear. Palpitoad with larger lumps on their bodies can sing with a wider range of sounds.'),
(537, NULL, 'Seismitoad', '537.png', 'Vibration Pokémon', 'Water', 'Ground', 'The vibrating of the bumps all over its body causes earthquake-like tremors. Seismitoad and Croagunk are similar species.'),
(538, NULL, 'Throh', '538.png', 'Judo Pokémon', 'Fighting', NULL, 'It performs throwing moves with first-rate skill. Over the course of many battles, Throh''s belt grows darker as it absorbs its wearer''s sweat.'),
(539, NULL, 'Sawk', '539.png', 'Karate Pokémon', 'Fighting', NULL, 'If you see a Sawk training in the mountains in its single-minded pursuit of strength, it''s best to quietly pass by.'),
(540, NULL, 'Sewaddle', '540.png', 'Sewing Pokémon', 'Bug', 'Grass', 'Since this Pokémon makes its own clothes out of leaves, it is a popular mascot for fashion designers.'),
(541, NULL, 'Swadloon', '541.png', 'Leaf-Wrapped Pokémon', 'Bug', 'Grass', 'It protects itself from the cold by wrapping up in leaves. It stays on the move, eating leaves in forests.'),
(542, NULL, 'Leavanny', '542.png', 'Nurturing Pokémon', 'Bug', 'Grass', 'It keeps its eggs warm with heat from fermenting leaves. It also uses leaves to make warm wrappings for Sewaddle.'),
(543, NULL, 'Venipede', '543.png', 'Centipede Pokémon', 'Bug', 'Poison', 'Its fangs are highly venomous. If this Pokémon finds prey it thinks it can eat, it leaps for them without any thought of how things might turn out.'),
(544, NULL, 'Whirlipede', '544.png', 'Curlipede Pokémon', 'Bug', 'Poison', 'Whirlipede protects itself with a sturdy shell and poisonous spikes while it stores up the energy it''ll need for evolution.'),
(545, NULL, 'Scolipede', '545.png', 'Megapede Pokémon', 'Bug', 'Poison', 'Scolipede latches on to its prey with the claws on its neck before slamming them into the ground and jabbing them with its claws'' toxic spikes.'),
(546, NULL, 'Cottonee', '546.png', 'Cotton Puff Pokémon', 'Grass', 'Fairy', 'It shoots cotton from its body to protect itself. If it gets caught up in hurricane-strength winds, it can get sent to the other side of the Earth.'),
(547, NULL, 'Whimsicott', '547.png', 'Windveiled Pokémon', 'Grass', 'Fairy', 'As long as this Pokémon bathes in sunlight, its cotton keeps growing. If too much cotton fluff builds up, Whimsicott tears it off and scatters it.'),
(548, NULL, 'Petilil', '548.png', 'Bulb Pokémon', 'Grass', NULL, 'If the leaves on its head are pruned with regularity, this Pokémon can be grown into a fine plump shape.'),
(549, NULL, 'Lilligant', '549.png', 'Flowering Pokémon', 'Grass', NULL, 'No matter how much time and money is spent raising it, its flowers are the most beautiful when they bloom in the wild.'),
(549, 3, 'Lilligant', '549-hisui.png', 'Spinning Pokémon', 'Grass', 'Fighting', 'I suspect that its well-developed legs are the result of a life spent on mountains covered in deep snow. The scent it exudes from its flower crown heartens those in proximity.'),
(550, NULL, 'Basculin', '550.png', 'Hostile Pokémon', 'Water', NULL, 'Red and blue Basculin get along so poorly, they''ll start fighting instantly. These Pokémon are very hostile.'),
(551, NULL, 'Sandile', '551.png', 'Desert Croc Pokémon', 'Ground', 'Dark', 'They live hidden under hot desert sands in order to keep their body temperature from dropping.'),
(552, NULL, 'Krokorok', '552.png', 'Desert Croc Pokémon', 'Ground', 'Dark', 'Thanks to the special membrane covering its eyes, it can see its surroundings clearly, even in the middle of the night.'),
(553, NULL, 'Krookodile', '553.png', 'Intimidation Pokémon', 'Ground', 'Dark', 'Its unique faculty of sight can detect small prey more than 30 miles away, even in the midst of a sandstorm.'),
(554, NULL, 'Darumaka', '554.png', 'Zen Charm Pokémon', 'Fire', NULL, 'This popular symbol of good fortune will never fall over in its sleep, no matter how it''s pushed or pulled.'),
(554, 2, 'Darumaka', '554-galar.png', 'Zen Charm Pokémon', 'Ice', NULL, 'It lived in snowy areas for so long that its fire sac cooled off and atrophied. It now has an organ that generates cold instead.'),
(555, NULL, 'Darmanitan', '555.png', 'Blazing Pokémon', 'Fire', NULL, 'Its internal fire burns at 2,500 degrees Fahrenheit, making enough power that it can destroy a dump truck with one punch.'),
(555, 2, 'Darmanitan', '555-galar.png', 'Zen Charm Pokémon', 'Ice', NULL, 'On days when blizzards blow through, it comes down to where people live. It stashes food in the snowball on its head, taking it home for later.'),
(556, NULL, 'Maractus', '556.png', 'Cactus Pokémon', 'Grass', NULL, 'With noises that could be mistaken for the rattles of maracas, it creates an upbeat rhythm, startling bird Pokémon and making them fly off in a hurry.'),
(557, NULL, 'Dwebble', '557.png', 'Rock Inn Pokémon', 'Bug', 'Rock', 'It first tries to find a rock to live in, but if there are no suitable rocks to be found, Dwebble may move in to the ports of a Hippowdon.'),
(558, NULL, 'Crustle', '558.png', 'Stone Home Pokémon', 'Bug', 'Rock', 'Its thick claws are its greatest weapons. They''re mighty enough to crack Rhyperior''s carapace.'),
(559, NULL, 'Scraggy', '559.png', 'Shedding Pokémon', 'Dark', 'Fighting', 'It protects itself with its durable skin. It''s thought that this Pokémon will evolve once its skin has completely stretched out.'),
(560, NULL, 'Scrafty', '560.png', 'Hoodlum Pokémon', 'Dark', 'Fighting', 'While mostly known for having the temperament of an aggressive ruffian, this Pokémon takes very good care of its family, friends, and territory.'),
(561, NULL, 'Sigilyph', '561.png', 'Avianoid Pokémon', 'Psychic', 'Flying', 'A discovery was made in the desert where Sigilyph fly. The ruins of what may have been an ancient city were found beneath the sands.'),
(562, NULL, 'Yamask', '562.png', 'Spirit Pokémon', 'Ghost', NULL, 'The spirit of a person from a bygone age became this Pokémon. It rambles through ruins, searching for someone who knows its face.'),
(562, 2, 'Yamask', '562-galar.png', 'Spirit Pokémon', 'Ground', 'Ghost', 'A clay slab with cursed engravings took possession of a Yamask. The slab is said to be absorbing the Yamask''s dark power.'),
(563, NULL, 'Cofagrigus', '563.png', 'Coffin Pokémon', 'Ghost', NULL, 'There are many depictions of Cofagrigus decorating ancient tombs. They''re symbols of the wealth that kings of bygone eras had.'),
(564, NULL, 'Tirtouga', '564.png', 'Prototurtle Pokémon', 'Water', 'Rock', 'Tirtouga is considered to be the ancestor of many turtle Pokémon. It was restored to life from a fossil.'),
(565, NULL, 'Carracosta', '565.png', 'Prototurtle Pokémon', 'Water', 'Rock', 'This Pokémon emerges from the water in search of prey despite the fact that it moves more slowly on land.'),
(566, NULL, 'Archen', '566.png', 'First Bird Pokémon', 'Rock', 'Flying', 'Archen is said to be the ancestor of bird Pokémon. It lived in treetops, eating berries and bug Pokémon.'),
(567, NULL, 'Archeops', '567.png', 'First Bird Pokémon', 'Rock', 'Flying', 'Though capable of flight, Archeops was apparently better at hunting on the ground.'),
(568, NULL, 'Trubbish', '568.png', 'Trash Bag Pokémon', 'Poison', NULL, 'Its favorite places are unsanitary ones. If you leave trash lying around, you could even find one of these Pokémon living in your room.'),
(569, NULL, 'Garbodor', '569.png', 'Trash Heap Pokémon', 'Poison', NULL, 'The toxic liquid it launches from its right arm is so virulent that it can kill a weakened creature instantly.'),
(570, NULL, 'Zorua', '570.png', 'Tricky Fox Pokémon', 'Dark', NULL, 'To protect themselves from danger, they hide their true identities by transforming into people and Pokémon.'),
(570, 3, 'Zorua', '570-hisui.png', 'Spiteful Fox Pokémon', 'Normal', 'Ghost', 'A once-departed soul, returned to life in Hisui. Derives power from resentment, which rises as energy atop its head and takes on the forms of foes. In this way, Zorua vents lingering malice.'),
(571, NULL, 'Zoroark', '571.png', 'Illusion Fox Pokémon', 'Dark', NULL, 'Each has the ability to fool a large group of people simultaneously. They protect their lair with illusory scenery.'),
(571, 3, 'Zoroark', '571-hisui.png', 'Baneful Fox Pokémon', 'Normal', 'Ghost', 'With its disheveled white fur, it looks like an embodiment of death. Heedless of its own safety, Zoroark attacks its nemeses with a bitter energy so intense, it lacerates Zoroark''s own body.'),
(572, NULL, 'Minccino', '572.png', 'Chinchilla Pokémon', 'Normal', NULL, 'They pet each other with their tails as a form of greeting. Of the two, the one whose tail is fluffier is a bit more boastful.'),
(573, NULL, 'Cinccino', '573.png', 'Scarf Pokémon', 'Normal', NULL, 'A special oil that seeps through their fur helps them avoid attacks. The oil fetches a high price at market.'),
(574, NULL, 'Gothita', '574.png', 'Fixation Pokémon', 'Psychic', NULL, 'Beware of touching the ribbon-shaped feelers that control its psychic power. Gothita will begin bawling if you do.'),
(575, NULL, 'Gothorita', '575.png', 'Manipulate Pokémon', 'Psychic', NULL, 'Using its psychic power, it arranges pebbles to form the shapes of constellations. Some people believe this Pokémon came from outer space.'),
(576, NULL, 'Gothitelle', '576.png', 'Astral Body Pokémon', 'Psychic', NULL, 'It gazes at the stars to predict the future. It acts somewhat detached because it has seen the end of all existence.'),
(577, NULL, 'Solosis', '577.png', 'Cell Pokémon', 'Psychic', NULL, 'Many say that the special liquid covering this Pokémon''s body would allow it to survive in the vacuum of space.'),
(578, NULL, 'Duosion', '578.png', 'Mitosis Pokémon', 'Psychic', NULL, 'Its brain has split into two, and the two halves rarely think alike. Its actions are utterly unpredictable.'),
(579, NULL, 'Reuniclus', '579.png', 'Multiplying Pokémon', 'Psychic', NULL, 'It''s said that drinking the liquid surrounding Reuniclus grants wisdom. Problem is, the liquid is highly toxic to anything besides Reuniclus itself.'),
(580, NULL, 'Ducklett', '580.png', 'Water Bird Pokémon', 'Water', 'Flying', 'They are better at swimming than flying, and they happily eat their favorite food, peat moss, as they dive underwater.'),
(581, NULL, 'Swanna', '581.png', 'White Bird Pokémon', 'Water', 'Flying', 'Swanna start to dance at dusk. The one dancing in the middle is the leader of the flock.'),
(582, NULL, 'Vanillite', '582.png', 'Fresh Snow Pokémon', 'Ice', NULL, 'Supposedly, this Pokémon was born from an icicle. It spews out freezing air at -58 degrees Fahrenheit to make itself more comfortable.'),
(583, NULL, 'Vanillish', '583.png', 'Icy Snow Pokémon', 'Ice', NULL, 'It blasts enemies with cold air reaching -148 degrees Fahrenheit, freezing them solid. But it spares their lives afterward—it''s a kind Pokémon.'),
(584, NULL, 'Vanilluxe', '584.png', 'Snowstorm Pokémon', 'Ice', NULL, 'People believe this Pokémon formed when two Vanillish stuck together. Its body temperature is roughly 21 degrees Fahrenheit.'),
(585, NULL, 'Deerling', '585.png', 'Season Pokémon', 'Normal', 'Grass', 'The turning of the seasons changes the color and scent of this Pokémon''s fur. People use it to mark the seasons.'),
(586, NULL, 'Sawsbuck', '586.png', 'Season Pokémon', 'Normal', 'Grass', 'They migrate according to the seasons, so some people call Sawsbuck the harbingers of spring.'),
(587, NULL, 'Emolga', '587.png', 'Sky Squirrel Pokémon', 'Electric', 'Flying', 'This Pokémon absolutely loves sweet berries. Sometimes it stuffs its cheeks full of so much food that it can''t fly properly.'),
(588, NULL, 'Karrablast', '588.png', 'Clamping Pokémon', 'Bug', NULL, 'It spits a liquid from its mouth to melt through Shelmet''s shell. Karrablast doesn''t eat the shell— it eats only the contents.'),
(589, NULL, 'Escavalier', '589.png', 'Cavalry Pokémon', 'Bug', 'Steel', 'These Pokémon evolve by wearing the shell covering of a Shelmet. The steel armor protects their whole body.'),
(590, NULL, 'Foongus', '590.png', 'Mushroom Pokémon', 'Grass', 'Poison', 'This Pokémon prefers damp places. It spurts out poison spores to repel approaching enemies.'),
(591, NULL, 'Amoonguss', '591.png', 'Mushroom Pokémon', 'Grass', 'Poison', 'Amoonguss mimics Poke Balls. It is not yet clear whether this mimicry is effective against other Pokémon.'),
(592, NULL, 'Frillish', '592.png', 'Floating Pokémon', 'Water', 'Ghost', 'Using the invisible poison spikes on its veillike arms and legs, it paralyzes its enemies and causes them to drown.'),
(593, NULL, 'Jellicent', '593.png', 'Floating Pokémon', 'Water', 'Ghost', 'Fishermen are terrified of Jellicent. It''s rumored to drag them into the sea and steal their lives away.'),
(594, NULL, 'Alomomola', '594.png', 'Caring Pokémon', 'Water', NULL, 'They float upon the open sea. Many water Pokémon gather in the area around Alomomola.'),
(595, NULL, 'Joltik', '595.png', 'Attaching Pokémon', 'Bug', 'Electric', 'Joltik can be found clinging to other Pokémon. It''s soaking up static electricity because it can''t produce a charge on its own.'),
(596, NULL, 'Galvantula', '596.png', 'EleSpider Pokémon', 'Bug', 'Electric', 'It lays traps of electrified threads near the nests of bird Pokémon, aiming to snare chicks that are not yet good at flying.'),
(597, NULL, 'Ferroseed', '597.png', 'Thorn Seed Pokémon', 'Grass', 'Steel', 'Mossy caves are their preferred dwellings. Enzymes contained in mosses help Ferroseed''s spikes grow big and strong.'),
(598, NULL, 'Ferrothorn', '598.png', 'Thorn Pod Pokémon', 'Grass', 'Steel', 'Its spikes are harder than steel. This Pokémon crawls across rock walls by stabbing the spikes on its feelers into the stone.'),
(599, NULL, 'Klink', '599.png', 'Gear Pokémon', 'Steel', NULL, 'It''s suspected that Klink were the inspiration behind ancient people''s invention of the first gears.'),
(600, NULL, 'Klang', '600.png', 'Gear Pokémon', 'Steel', NULL, 'When Klang goes all out, the minigear links up perfectly with the outer part of the big gear, and this Pokémon''s rotation speed increases sharply.'),
(601, NULL, 'Klinklang', '601.png', 'Gear Pokémon', 'Steel', NULL, 'The three gears that compose this Pokémon spin at high speed. Its new spiked gear isn''t a living creature.'),
(602, NULL, 'Tynamo', '602.png', 'EleFish Pokémon', 'Electric', NULL, 'These Pokémon move in schools. They have an electricity-generating organ, so they discharge electricity if in danger.'),
(603, NULL, 'Eelektrik', '603.png', 'EleFish Pokémon', 'Electric', NULL, 'These Pokémon have a big appetite. When they spot their prey, they attack it and paralyze it with electricity.'),
(604, NULL, 'Eelektross', '604.png', 'EleFish Pokémon', 'Electric', NULL, 'It latches on to prey with its sucker mouth, sinking in its fangs and shocking the prey with powerful electricity.'),
(605, NULL, 'Elgyem', '605.png', 'Cerebral Pokémon', 'Psychic', NULL, 'This Pokémon was discovered about 50 years ago. Its highly developed brain enables it to exert its psychic powers.'),
(606, NULL, 'Beheeyem', '606.png', 'Cerebral Pokémon', 'Psychic', NULL, 'Sometimes found drifting above wheat fields, this Pokémon can control the memories of its opponents.'),
(607, NULL, 'Litwick', '607.png', 'Candle Pokémon', 'Ghost', 'Fire', 'The flame on its head keeps its body slightly warm. This Pokémon takes lost children by the hand to guide them to the spirit world.'),
(608, NULL, 'Lampent', '608.png', 'Lamp Pokémon', 'Ghost', 'Fire', 'It lurks in cities, pretending to be a lamp. Once it finds someone whose death is near, it will trail quietly after them.'),
(609, NULL, 'Chandelure', '609.png', 'Luring Pokémon', 'Ghost', 'Fire', 'In homes illuminated by Chandelure instead of lights, funerals were a constant occurrence- or so it''s said.'),
(610, NULL, 'Axew', '610.png', 'Tusk Pokémon', 'Dragon', NULL, 'If you see peculiar teeth marks on boulders or trees, it means an Axew is likely living nearby.'),
(611, NULL, 'Fraxure', '611.png', 'Axe Jaw Pokémon', 'Dragon', NULL, 'Fraxure uses its thick tusks to neatly cut prey into two portions—one to eat now and one to save for later.'),
(612, NULL, 'Haxorus', '612.png', 'Axe Jaw Pokémon', 'Dragon', NULL, 'It overwhelms enemies with its prized tusks, which are sharp enough to cut through a metal transmission tower in one strike.'),
(613, NULL, 'Cubchoo', '613.png', 'Chill Pokémon', 'Ice', NULL, 'When Cubchoo starts sneezing, watch out! If it spatters you with its frosty snot, you''ll get frostbite.'),
(614, NULL, 'Beartic', '614.png', 'Freezing Pokémon', 'Ice', NULL, 'Feared as the Snow-White Demon in northern lands, Beartic uses its frosty claws and fangs to attack prey.'),
(615, NULL, 'Cryogonal', '615.png', 'Crystallizing Pokémon', 'Ice', NULL, 'Cryogonal uses its chains of ice to constrict its opponents and then flash-freezes them where they stand.'),
(616, NULL, 'Shelmet', '616.png', 'Snail Pokémon', 'Bug', NULL, 'It has a strange physiology that responds to electricity. When together with Karrablast, Shelmet evolves for some reason.'),
(617, NULL, 'Accelgor', '617.png', 'Shell Out Pokémon', 'Bug', NULL, 'It moves with blinding speed and lobs poison at foes. Featuring Accelgor as a main character is a surefire way to make a movie or comic popular.'),
(618, NULL, 'Stunfisk', '618.png', 'Trap Pokémon', 'Ground', 'Electric', 'For some reason, this Pokémon smiles slightly when it emits a strong electric current from the yellow markings on its body.'),
(618, 2, 'Stunfisk', '618-galar.png', 'Trap Pokémon', 'Ground', 'Steel', 'Its conspicuous lips lure prey in as it lies in wait in the mud. When prey gets close, Stunfisk clamps its jagged steel fins down on them.'),
(619, NULL, 'Mienfoo', '619.png', 'Martial Arts Pokémon', 'Fighting', NULL, 'Though small, Mienfoo''s temperament is fierce. Any creature that approaches Mienfoo carelessly will be greeted with a flurry of graceful attacks.'),
(620, NULL, 'Mienshao', '620.png', 'Martial Arts Pokémon', 'Fighting', NULL, 'Delivered at blinding speeds, kicks from this Pokémon can shatter massive boulders into tiny pieces.'),
(621, NULL, 'Druddigon', '621.png', 'Cave Pokémon', 'Dragon', NULL, 'Druddigon are vicious and cunning. They take up residence in nests dug out by other Pokémon, treating the stolen nests as their own lairs.'),
(622, NULL, 'Golett', '622.png', 'Automaton Pokémon', 'Ground', 'Ghost', 'This Pokémon was created from clay. It received orders from its master many thousands of years ago, and it still follows those orders to this day.'),
(623, NULL, 'Golurk', '623.png', 'Automaton Pokémon', 'Ground', 'Ghost', 'There''s a theory that inside Golurk is a perpetual motion machine that produces limitless energy, but this belief hasn''t been proven.'),
(624, NULL, 'Pawniard', '624.png', 'Sharp Blade Pokémon', 'Dark', 'Steel', 'Any chips in its blades would prove fatal for it. After each battle, it diligently maintains its blades using its favorite sharpening stone.'),
(625, NULL, 'Bisharp', '625.png', 'Sword Blade Pokémon', 'Dark', 'Steel', 'Bisharp mercilessly cuts its opponents to pieces with the sharp blades covering its body. It will do anything to win.'),
(626, NULL, 'Bouffalant', '626.png', 'Bash Buffalo Pokémon', 'Normal', NULL, 'These Pokémon live in herds of about 20 individuals. Bouffalant that betray the herd will lose the hair on their heads for some reason.'),
(627, NULL, 'Rufflet', '627.png', 'Eaglet Pokémon', 'Normal', 'Flying', 'With its sharp claws, this Pokémon pierces its prey, and then it pecks at them. Although it also consumes berries, it''s a carnivore at heart.'),
(628, NULL, 'Braviary', '628.png', 'Valiant Pokémon', 'Normal', 'Flying', 'For the sake of its friends, this brave warrior of the sky will not stop battling, even if injured.'),
(628, 3, 'Braviary', '628-hisui.png', 'Battle Cry Pokémon', 'Psychic', 'Flying', 'Screaming a bloodcurdling battle cry, this huge and ferocious bird Pokémon goes out on the hunt. It blasts lakes with shock waves, then scoops up any prey that float to the water''s surface.'),
(629, NULL, 'Vullaby', '629.png', 'Diapered Pokémon', 'Dark', 'Flying', 'Vullaby grow quickly. Bones that have gotten too small for older Vullaby to wear often get passed down to younger ones in the nest.'),
(630, NULL, 'Mandibuzz', '630.png', 'Bone Vulture Pokémon', 'Dark', 'Flying', 'They adorn themselves with bones. There seem to be fashion trends among them, as different bones come into and fall out of popularity.'),
(631, NULL, 'Heatmor', '631.png', 'Anteater Pokémon', 'Fire', NULL, 'A flame serves as its tongue, melting through the hard shell of Durant so that Heatmor can devour their insides.'),
(632, NULL, 'Durant', '632.png', 'Iron Ant Pokémon', 'Bug', 'Steel', 'They lay their eggs deep inside their nests. When attacked by Heatmor, they retaliate using their massive mandibles.'),
(633, NULL, 'Deino', '633.png', 'Irate Pokémon', 'Dark', 'Dragon', 'It nests deep inside a cave. Food there is scarce, so Deino will sink its teeth into anything that moves and attempt to eat it.'),
(634, NULL, 'Zweilous', '634.png', 'Hostile Pokémon', 'Dark', 'Dragon', 'The two heads have different likes and dislikes. Because the heads fight with each other, Zweilous gets stronger without needing to rely on others.'),
(635, NULL, 'Hydreigon', '635.png', 'Brutal Pokémon', 'Dark', 'Dragon', 'It''s said that Hydreigon grew ferocious because people in times long past loathed it, considering it to be evil incarnate and attacking it relentlessly.'),
(636, NULL, 'Larvesta', '636.png', 'Torch Pokémon', 'Bug', 'Fire', 'In ancient times, Larvesta was worshiped as the emissary of the sun. However, it was also viewed as a burden since it often caused forest fires.'),
(637, NULL, 'Volcarona', '637.png', 'Sun Pokémon', 'Bug', 'Fire', 'This Pokémon scatters burning scales. Most of the danger of these scales is not in their heat—it''s in the way they rob the surrounding air of oxygen.'),
(638, NULL, 'Cobalion', '638.png', 'Iron Will Pokémon', 'Steel', 'Fighting', 'This Pokémon appears in a legend alongside Terrakion and Virizion, fighting against humans in defense of the Unova region''s Pokémon.'),
(639, NULL, 'Terrakion', '639.png', 'Cavern Pokémon', 'Rock', 'Fighting', 'In Unovan legend, Terrakion battled against humans in an effort to protect other Pokémon.'),
(640, NULL, 'Virizion', '640.png', 'Grassland Pokémon', 'Grass', 'Fighting', 'A legend tells of this Pokémon working together with Cobalion and Terrakion to protect the Pokémon of the Unova region.'),
(641, NULL, 'Tornadus', '641.png', 'Cyclone Pokémon', 'Flying', NULL, 'Tornadus expels massive energy from its tail, causing severe storms. Its power is great enough to blow houses away.'),
(642, NULL, 'Thundurus', '642.png', 'Bolt Strike Pokémon', 'Electric', 'Flying', 'They say this wielder of electricity has waged war with its nemesis, Tornadus, since time immemorial. The lightning bolts it hurls pierce the very earth and enrich the soil.'),
(643, NULL, 'Reshiram', '643.png', 'Vast White Pokémon', 'Dragon', 'Fire', 'According to myth, if people ignore truth and let themselves become consumed by greed, Reshiram will arrive to burn their kingdoms down.'),
(644, NULL, 'Zekrom', '644.png', 'Deep Black Pokémon', 'Dragon', 'Electric', 'Mythology tells us that if people lose the righteousness in their hearts, their kingdoms will be razed by Zekrom''s lightning.'),
(645, NULL, 'Landorus', '645.png', 'Abundance Pokémon', 'Ground', 'Flying', 'From the forces of lightning and wind, it creates energy to give nutrients to the soil and make the land abundant.'),
(646, NULL, 'Kyurem', '646.png', 'Boundary Pokémon', 'Dragon', 'Ice', 'It appears that this Pokémon uses its powers over ice to freeze its own body in order to stabilize its cellular structure.'),
(647, NULL, 'Keldeo', '647.png', 'Colt Pokémon', 'Water', 'Fighting', 'When it is resolute, its body fills with power and it becomes swifter. Its jumps are then too fast to follow.'),
(648, NULL, 'Meloetta', '648.png', 'Melody Pokémon', 'Normal', 'Psychic', 'Its melodies are sung with a special vocalization method that can control the feelings of those who hear it.'),
(649, NULL, 'Genesect', '649.png', 'Paleozoic Pokémon', 'Bug', 'Steel', 'This Pokémon existed 300 million years ago. Team Plasma altered it and attached a cannon to its back.'),
(650, NULL, 'Chespin', '650.png', 'Spiny Nut Pokémon', 'Grass', NULL, 'Such a thick shell of wood covers its head and back that even a direct hit from a truck wouldn''t faze it.'),
(651, NULL, 'Quilladin', '651.png', 'Spiny Armor Pokémon', 'Grass', NULL, 'They strengthen their lower bodies by running into one another. They are very kind and won''t start fights.'),
(652, NULL, 'Chesnaught', '652.png', 'Spiny Armor Pokémon', 'Grass', 'Fighting', 'When it takes a defensive posture with its fists guarding its face, it could withstand a bomb blast.'),
(653, NULL, 'Fennekin', '653.png', 'Fox Pokémon', 'Fire', NULL, 'As it walks, it munches on a twig in place of a snack. It intimidates opponents by puffing hot air out of its ears.'),
(654, NULL, 'Braixen', '654.png', 'Fox Pokémon', 'Fire', NULL, 'When the twig is plucked from its tail, friction sets the twig alight. The flame is used to send signals to its allies.'),
(655, NULL, 'Delphox', '655.png', 'Fox Pokémon', 'Fire', 'Psychic', 'Using psychic power, it generates a fiery vortex of 5,400 degrees Fahrenheit, incinerating foes swept into this whirl of flame.'),
(656, NULL, 'Froakie', '656.png', 'Bubble Frog Pokémon', 'Water', NULL, 'It protects its skin by covering its body in delicate bubbles. Beneath its happy-go-lucky air, it keeps a watchful eye on its surroundings.'),
(657, NULL, 'Frogadier', '657.png', 'Bubble Frog Pokémon', 'Water', NULL, 'Its swiftness is unparalleled. It can scale a tower of more than 2,000 feet in a minute''s time.'),
(658, NULL, 'Greninja', '658.png', 'Ninja Pokémon', 'Water', 'Dark', 'It appears and vanishes with a ninja''s grace. It toys with its enemies using swift movements, while slicing them with throwing stars of sharpest water.'),
(659, NULL, 'Bunnelby', '659.png', 'Digging Pokémon', 'Normal', NULL, 'It excels at digging holes. Using its ears, it can dig a nest 33 feet deep in one night.'),
(660, NULL, 'Diggersby', '660.png', 'Digging Pokémon', 'Normal', 'Ground', 'The fur on its belly retains heat exceptionally well. People used to make heavy winter clothing from fur shed by this Pokémon.'),
(661, NULL, 'Fletchling', '661.png', 'Tiny Robin Pokémon', 'Normal', 'Flying', 'This Pokémon is normally calm, but once it enters battle, its hormonal balance changes and it becomes aggressive.'),
(662, NULL, 'Fletchinder', '662.png', 'Ember Pokémon', 'Fire', 'Flying', 'Its territory has a radius of just over a mile. If any bird Pokémon should enter, it will show them no mercy.'),
(663, NULL, 'Talonflame', '663.png', 'Scorching Pokémon', 'Fire', 'Flying', 'When it gets excited, it vents sparks from the gaps between its feathers. These unburnable feathers are used as a fireproof material.'),
(664, NULL, 'Scatterbug', '664.png', 'Scatterdust Pokémon', 'Bug', NULL, 'This Pokémon scatters poisonous powder to repel enemies. It will eat different plants depending on where it lives.'),
(665, NULL, 'Spewpa', '665.png', 'Scatterdust Pokémon', 'Bug', NULL, 'Spewpa doesn''t live in a fixed location. It roams where it pleases across the fields and mountains, building up the energy it needs to evolve.'),
(666, NULL, 'Vivillon', '666.png', 'Scale Pokémon', 'Bug', 'Flying', 'Vivillon with many different patterns are found all over the world. These patterns are affected by the climate of their habitat.'),
(667, NULL, 'Litleo', '667.png', 'Lion Cub Pokémon', 'Fire', 'Normal', 'When Litleo are young, female Pyroar will teach them how to hunt. Once the Litleo mature, they will leave the pride and set out on their own.'),
(668, NULL, 'Pyroar', '668.png', 'Royal Pokémon', 'Fire', 'Normal', 'With fiery breath of more than 10,000 degrees Fahrenheit, they viciously threaten any challenger. The females protect the pride''s cubs.'),
(669, NULL, 'Flabébé', '669.png', 'Single Bloom Pokémon', 'Fairy', NULL, 'It''s not safe without the power of a flower, but it will keep traveling around until it finds one with the color and shape it wants.'),
(670, NULL, 'Floette', '670.png', 'Single Bloom Pokémon', 'Fairy', NULL, 'It gives its own power to flowers, pouring its heart into caring for them. Floette never forgives anyone who messes up a flower bed.'),
(671, NULL, 'Florges', '671.png', 'Garden Pokémon', 'Fairy', NULL, 'Its life can span several hundred years. It''s said to devote its entire life to protecting gardens.'),
(672, NULL, 'Skiddo', '672.png', 'Mount Pokémon', 'Grass', NULL, 'As long as it has sunlight and water, Skiddo can make energy with the leaves on its body, allowing it to live on rocky mountains barren of food.'),
(673, NULL, 'Gogoat', '673.png', 'Mount Pokémon', 'Grass', NULL, 'It can sense the feelings of others by touching them with its horns. This species has assisted people with their work since 5,000 years ago.'),
(674, NULL, 'Pancham', '674.png', 'Playful Pokémon', 'Fighting', NULL, 'Wanting to make sure it''s taken seriously, Pancham''s always giving others a glare. But if it''s not focusing, it ends up smiling.'),
(675, NULL, 'Pangoro', '675.png', 'Daunting Pokémon', 'Fighting', 'Dark', 'Using its leaf, Pangoro can predict the moves of its opponents. It strikes with punches that can turn a dump truck into scrap with just one hit.'),
(676, NULL, 'Furfrou', '676.png', 'Poodle Pokémon', 'Normal', NULL, 'There was an era when aristocrats would compete to see who could trim their Furfrou''s fur into the most exquisite style.'),
(677, NULL, 'Espurr', '677.png', 'Restraint Pokémon', 'Psychic', NULL, 'There''s enough psychic power in Espurr to send a wrestler flying, but because this power can''t be controlled, Espurr finds it troublesome.'),
(678, NULL, 'Meowstic', '678.png', 'Constraint Pokémon', 'Psychic', NULL, 'The eyeball patterns on the interior of its ears emit psychic energy. It keeps the patterns tightly covered because that power is too immense.'),
(679, NULL, 'Honedge', '679.png', 'Sword Pokémon', 'Steel', 'Ghost', 'The blue eye on the sword''s handguard is the true body of Honedge. With its old cloth, it drains people''s lives away.'),
(680, NULL, 'Doublade', '680.png', 'Sword Pokémon', 'Steel', 'Ghost', 'The two swords employ a strategy of rapidly alternating between offense and defense to bring down their prey.'),
(681, NULL, 'Aegislash', '681.png', 'Royal Sword Pokémon', 'Steel', 'Ghost', 'Apparently, it can detect the innate qualities of leadership. According to legend, whoever it recognizes is destined to become king.'),
(682, NULL, 'Spritzee', '682.png', 'Perfume Pokémon', 'Fairy', NULL, 'The scent its body gives off enraptures those who smell it. Noble ladies had no shortage of love for Spritzee.'),
(683, NULL, 'Aromatisse', '683.png', 'Fragrance Pokémon', 'Fairy', NULL, 'The scents Aromatisse can produce range from sweet smells that bolster allies to foul smells that sap an opponent''s will to fight.'),
(684, NULL, 'Swirlix', '684.png', 'Cotton Candy Pokémon', 'Fairy', NULL, 'The sweet smell of cotton candy perfumes Swirlix''s fluffy fur. This Pokémon spits out sticky string to tangle up its enemies.'),
(685, NULL, 'Slurpuff', '685.png', 'Meringue Pokémon', 'Fairy', NULL, 'Slurpuff''s fur contains a lot of air, making it soft to the touch and lighter than it looks.'),
(686, NULL, 'Inkay', '686.png', 'Revolving Pokémon', 'Dark', 'Psychic', 'By exposing foes to the blinking of its luminescent spots, Inkay demoralizes them, and then it seizes the chance to flee.'),
(687, NULL, 'Malamar', '687.png', 'Overturning Pokémon', 'Dark', 'Psychic', 'Gazing at its luminescent spots will quickly induce a hypnotic state, putting the observer under Malamar''s control.'),
(688, NULL, 'Binacle', '688.png', 'Two-Handed Pokémon', 'Rock', 'Water', 'After two Binacle find a suitably sized rock, they adhere themselves to it and live together. They cooperate to gather food during high tide.'),
(689, NULL, 'Barbaracle', '689.png', 'Collective Pokémon', 'Rock', 'Water', 'Having an eye on each palm allows it to keep watch in all directions. In a pinch, its limbs start to act on their own to ensure the enemy''s defeat.'),
(690, NULL, 'Skrelp', '690.png', 'Mock Kelp Pokémon', 'Poison', 'Water', 'This Pokémon is a poor swimmer. If it''s caught in a fierce storm, it will sometimes get washed far away and become unable to return to its home.'),
(691, NULL, 'Dragalge', '691.png', 'Mock Kelp Pokémon', 'Poison', 'Dragon', 'Using a liquid poison, Dragalge indiscriminately attacks anything that wanders into its territory. This poison can corrode the undersides of boats.'),
(692, NULL, 'Clauncher', '692.png', 'Water Gun Pokémon', 'Water', NULL, 'Clauncher''s claws will regrow if they fall off. The meat inside the claws is edible, but it has a distinct flavor that doesn''t appeal to all tastes.'),
(693, NULL, 'Clawitzer', '693.png', 'Howitzer Pokémon', 'Water', NULL, 'The cannonballs of seawater that Clawitzer launches from its claw are powerful enough to punch through tanker hulls.'),
(694, NULL, 'Helioptile', '694.png', 'Generator Pokémon', 'Electric', 'Normal', 'When spread, the frills on its head act like solar panels, generating the power behind this Pokémon''s electric moves.'),
(695, NULL, 'Heliolisk', '695.png', 'Generator Pokémon', 'Electric', 'Normal', 'One Heliolisk basking in the sun with its frill outspread is all it would take to produce enough electricity to power a city.'),
(696, NULL, 'Tyrunt', '696.png', 'Royal Heir Pokémon', 'Rock', 'Dragon', 'This Pokémon is selfish and likes to be pampered. It can also inflict grievous wounds on its Trainer just by playing around.'),
(697, NULL, 'Tyrantrum', '697.png', 'Despot Pokémon', 'Rock', 'Dragon', 'A single bite of Tyrantrum''s massive jaws will demolish a car. This Pokémon was the king of the ancient world.'),
(698, NULL, 'Amaura', '698.png', 'Tundra Pokémon', 'Rock', 'Ice', 'Amaura is an ancient Pokémon that has gone extinct. Specimens of this species can sometimes be found frozen in ice.'),
(699, NULL, 'Aurorus', '699.png', 'Tundra Pokémon', 'Rock', 'Ice', 'Aurorus was restored from a fossil. It''s said that when this Pokémon howls, auroras appear in the night sky.'),
(700, NULL, 'Sylveon', '700.png', 'Intertwining Pokémon', 'Fairy', NULL, 'Sylveon cuts an elegant figure as it dances lightly around, feelers fluttering, but its piercing moves aim straight for its opponents'' weak spots.'),
(701, NULL, 'Hawlucha', '701.png', 'Wrestling Pokémon', 'Fighting', 'Flying', 'Hawlucha live quietly without flocking together. They fight constantly with their natural enemies: noisy groups of Primeape.'),
(702, NULL, 'Dedenne', '702.png', 'Antenna Pokémon', 'Electric', 'Fairy', 'Dedenne emit electrical waves from the whiskers on their cheeks to communicate with each other. When low on electricity, they curl up and sleep.'),
(703, NULL, 'Carbink', '703.png', 'Jewel Pokémon', 'Rock', 'Fairy', 'It''s said that somewhere in the world, there''s a mineral vein housing a large pack of slumbering Carbink. It''s also said that this pack has a queen.'),
(704, NULL, 'Goomy', '704.png', 'Soft Tissue Pokémon', 'Dragon', NULL, 'Goomy''s horns are excellent sensory organs that cover all five of Goomy''s senses. Goomy picks up on danger from the movement of the air.'),
(705, NULL, 'Sliggoo', '705.png', 'Soft Tissue Pokémon', 'Dragon', NULL, 'When Sliggoo senses danger, the mucus coating its entire body becomes more concentrated—it''ll dissolve anything.'),
(705, 3, 'Sliggoo', '705-hisui.png', 'Soft Tissue Pokémon', 'Steel', 'Dragon', 'A creature given to melancholy. I suspect its metallic shell developed as a result of the mucus on its skin reacting with the iron in Hisui''s water.'),
(706, NULL, 'Goodra', '706.png', 'Dragon Pokémon', 'Dragon', NULL, 'This Pokémon is uncontrollable when enraged. It rampages on and on, lashing its tail with enough power to send a dump truck flying.'),
(706, 3, 'Goodra', '706-hisui.png', 'Shell Bunker Pokémon', 'Steel', 'Dragon', 'Able to freely control the hardness of its metallic shell. It loathes solitude and is extremely clingy—it will fume and run riot if those dearest to it ever leave its side.'),
(707, NULL, 'Klefki', '707.png', 'Key Ring Pokémon', 'Steel', 'Fairy', 'In the past, noble families entrusted their vault keys to a Klefki. They passed the Klefki down through the generations, taking good care of it.'),
(708, NULL, 'Phantump', '708.png', 'Stump Pokémon', 'Ghost', 'Grass', 'With a voice like a human child''s, it cries out to lure adults deep into the forest, getting them lost among the trees.'),
(709, NULL, 'Trevenant', '709.png', 'Elder Tree Pokémon', 'Ghost', 'Grass', 'Small roots that extend from the tips of this Pokémon''s feet can tie into the trees of the forest and give Trevenant control over them.'),
(710, NULL, 'Pumpkaboo', '710.png', 'Pumpkin Pokémon', 'Ghost', 'Grass', 'The pumpkin body is inhabited by a spirit trapped in this world. As the sun sets, it becomes restless and active.'),
(711, NULL, 'Gourgeist', '711.png', 'Pumpkin Pokémon', 'Ghost', 'Grass', 'Singing in eerie voices, they wander town streets on the night of the new moon. Anyone who hears their song is cursed.'),
(712, NULL, 'Bergmite', '712.png', 'Ice Chunk Pokémon', 'Ice', NULL, 'Bergmite protects itself by coating its body in ice formed by frigid air of -148 degrees Fahrenheit. It fights with Frigibax whenever they meet.'),
(713, NULL, 'Avalugg', '713.png', 'Iceberg Pokémon', 'Ice', NULL, 'This Pokémon uses its massive icy body to flatten anything that gets in its way. When it''s floating out on the ocean, it looks exactly like drift ice.'),
(713, 3, 'Avalugg', '713-hisui.png', 'Iceberg Pokémon', 'Ice', 'Rock', 'The armor of ice covering its lower jaw puts steel to shame and can shatter rocks with ease. This Pokémon barrels along steep mountain paths, cleaving through the deep snow.'),
(714, NULL, 'Noibat', '714.png', 'Sound Wave Pokémon', 'Flying', 'Dragon', 'Noibat can change the frequency of its sound waves at will, and it generates ultrasonic waves of up to 200,000 hertz.'),
(715, NULL, 'Noivern', '715.png', 'Sound Wave Pokémon', 'Flying', 'Dragon', 'In the dark, even Hydreigon are terrified of this Pokémon. But in the light, Noivern is the one that avoids battle.'),
(716, NULL, 'Xerneas', '716.png', 'Life Pokémon', 'Fairy', NULL, 'When the horns on its head shine in seven colors, it is said to be sharing everlasting life.'),
(717, NULL, 'Yveltal', '717.png', 'Destruction Pokémon', 'Dark', 'Flying', 'When its life comes to an end, it absorbs the life energy of every living thing and turns into a cocoon once more.'),
(718, NULL, 'Zygarde', '718.png', 'Order Pokémon', 'Dragon', 'Ground', 'This is Zygarde''s form when about half of its pieces have been assembled. It plays the role of monitoring the ecosystem.'),
(719, NULL, 'Diancie', '719.png', 'Jewel Pokémon', 'Rock', 'Fairy', 'A sudden transformation of Carbink, its pink, glimmering body is said to be the loveliest sight in the whole world.'),
(720, NULL, 'Hoopa', '720.png', 'Mischief Pokémon', 'Psychic', 'Ghost', 'It is said to be able to seize anything it desires with its six rings and six huge arms. With its power sealed, it is transformed into a much smaller form.'),
(721, NULL, 'Volcanion', '721.png', 'Steam Pokémon', 'Fire', 'Water', 'It lets out billows of steam and disappears into the dense fog. It''s said to live in mountains where humans do not tread.'),
